insert into public.topic_ledger
  (topic_key, source, scripture, reference, title, theme, summary, citation_url, weight)
values
  ('purana:vishnu:dhruva', 'purana', 'Vishnu Purana', 'Book 1, Chapters 11–12', 'Dhruva, the boy who would not be moved', 'perseverance and single-minded resolve', 'Refused a seat on his father''s lap by his stepmother, the child Dhruva walks into the forest and undertakes austerity with such concentration that Vishnu appears before him. Dhruva, who began seeking a kingdom, finds he no longer wants one. He is fixed in the sky as the pole star — the one point that never wavers.', 'https://www.wisdomlib.org/hinduism/book/vishnu-purana-wilson', 130),
  ('purana:vishnu:prahlada', 'purana', 'Vishnu Purana', 'Book 1, Chapters 17–20', 'Prahlada, devotion that fire could not burn', 'unshakeable faith under persecution', 'Hiranyakashipu orders his own son killed for worshipping Vishnu. Prahlada is thrown from cliffs, given poison and cast into fire, and survives each time without hatred for his father. His answer is that the Lord is everywhere, including in the pillar — and in his tormentor.', 'https://www.wisdomlib.org/hinduism/book/vishnu-purana-wilson', 130),
  ('purana:vishnu:vena-prithu', 'purana', 'Vishnu Purana', 'Book 1, Chapter 13', 'King Vena and the earth that refused to yield', 'righteous leadership and responsibility', 'The tyrant Vena forbids worship and sacrifice, and the earth herself withholds her harvests. From his body arises Prithu, who rules by first winning the earth''s trust rather than commanding it. The land gives freely to the king who protects it.', 'https://www.wisdomlib.org/hinduism/book/vishnu-purana-wilson', 100),
  ('purana:vishnu:jada-bharata', 'purana', 'Vishnu Purana', 'Book 2, Chapters 13–16', 'Bharata and the fawn he could not stop loving', 'attachment quietly redirecting a life', 'The royal ascetic Bharata renounces a kingdom successfully, then loses his liberation to a single orphaned deer he cannot stop worrying about. Dying with the fawn in his mind, he is reborn as a deer. Reborn again as a man, he refuses to speak — and is mistaken for an idiot while carrying the highest knowledge.', 'https://www.wisdomlib.org/hinduism/book/vishnu-purana-wilson', 120),
  ('purana:vishnu:kapila-sagara', 'purana', 'Vishnu Purana', 'Book 4, Chapter 4', 'The sixty thousand sons of Sagara', 'arrogance and its long repair', 'Sagara''s sons tear up the earth searching for a stolen horse and accuse the meditating sage Kapila of the theft. Their insolence reduces them to ash. Generations later Bhagiratha brings down the Ganga to redeem them — one man''s patience repairing what pride destroyed.', 'https://www.wisdomlib.org/hinduism/book/vishnu-purana-wilson', 110),
  ('purana:vishnu:kali-yuga', 'purana', 'Vishnu Purana', 'Book 6, Chapters 1–2', 'The one advantage of the Kali age', 'hope in a difficult age', 'Parashara describes the degradations of the Kali age with unsparing clarity — then names its hidden gift. What took long penance in earlier ages is now attained by simply remembering the divine name with sincerity. The worst age is also the cheapest one in which to be liberated.', 'https://www.wisdomlib.org/hinduism/book/vishnu-purana-wilson', 125),
  ('purana:vishnu:krishna-govardhana', 'purana', 'Vishnu Purana', 'Book 5, Chapters 10–11', 'Govardhana lifted on a child''s finger', 'protection and the end of fear', 'Krishna persuades the cowherds to honour the hill that actually feeds their cattle instead of performing rote sacrifice to Indra. When the insulted Indra sends a week of storms, Krishna raises Govardhana on one finger and shelters everyone beneath it.', 'https://www.wisdomlib.org/hinduism/book/vishnu-purana-wilson', 130),
  ('purana:vishnu:parashara-anger', 'purana', 'Vishnu Purana', 'Book 1, Chapter 1', 'The sage who called off his own revenge', 'stopping a punishment already under way', 'Parashara begins a sacrifice to destroy every demon in the world for killing his father, and it is working. His grandfather asks him to stop — not because they are innocent, but because the anger is eating him. He stops, and then tells the whole Purana.', 'https://www.wisdomlib.org/hinduism/book/vishnu-purana-wilson', 130),
  ('purana:vishnu:raivata-return', 'purana', 'Vishnu Purana', 'Book 4, Chapter 1', 'He was gone for one conversation', 'coming back to a world that moved on', 'King Kakudmi takes his daughter to Brahma to ask whom she should marry, waits through a short piece of music, and is told that ages have passed on earth. Every suitor he had in mind is long dead, along with everyone who remembered him.', 'https://www.wisdomlib.org/hinduism/book/vishnu-purana-wilson', 135),
  ('purana:vishnu:kandu', 'purana', 'Vishnu Purana', 'Book 1, Chapter 15', 'The sage who asked her to wait a moment', 'time passing unnoticed inside pleasure', 'The ascetic Kandu lives with the nymph Pramlocha and asks her, each time she offers to leave, to stay a little longer. When he finally counts, several hundred years have gone by, and he is certain it was an afternoon.', 'https://www.wisdomlib.org/hinduism/book/vishnu-purana-wilson', 130),
  ('purana:vishnu:khandikya-keshidhvaja', 'purana', 'Vishnu Purana', 'Book 6, Chapters 6–7', 'He asked his enemy to teach him', 'taking help from the person who took everything', 'Two cousins have fought over one kingdom; one won the land, the other kept the learning. When the winner needs knowledge, he rides to the forest and puts his head down before the man he dispossessed — who teaches him, having first been offered the chance to kill him.', 'https://www.wisdomlib.org/hinduism/book/vishnu-purana-wilson', 130),
  ('purana:vishnu:pururavas', 'purana', 'Vishnu Purana', 'Book 4, Chapter 6', 'The conditions she set, and the night he broke them', 'a love lost on a technicality', 'Urvashi agrees to stay with Pururavas on conditions so small they seem safe: two lambs kept beside the bed, and he must never be seen unclothed. One night both are broken at once, by accident, and she is gone by morning.', 'https://www.wisdomlib.org/hinduism/book/vishnu-purana-wilson', 130),
  ('purana:bhagavata:gajendra', 'purana', 'Bhagavata Purana', 'Canto 8, Chapters 2–4', 'Gajendra: the cry that was finally answered', 'surrender at the end of self-effort', 'An elephant king seized by a crocodile fights for a thousand years on his own strength and slowly loses. Only when he stops struggling and lifts a single lotus in complete helplessness does Vishnu come. The moment of rescue is the moment of surrender, not the moment of effort.', 'https://www.wisdomlib.org/hinduism/book/the-bhagavata-purana', 135),
  ('purana:bhagavata:ajamila', 'purana', 'Bhagavata Purana', 'Canto 6, Chapters 1–2', 'Ajamila, saved by his son''s name', 'the power of the divine name', 'Ajamila abandons a life of virtue and falls badly. Dying in terror, he calls out for his youngest son — who happens to be named Narayana. Uttered without any devotion at all, the name still works, and he is given the rest of his life to mean it.', 'https://www.wisdomlib.org/hinduism/book/the-bhagavata-purana', 125),
  ('purana:bhagavata:avadhuta-24-gurus', 'purana', 'Bhagavata Purana', 'Canto 11, Chapters 7–9', 'The avadhuta''s twenty-four teachers', 'learning from everything around you', 'Asked why he is so serene, a wandering ascetic tells King Yadu he has had twenty-four gurus — the earth for patience under abuse, the wind for moving through the world untouched, the honeybee for taking a little from many flowers, the python for contentment with what comes.', 'https://www.wisdomlib.org/hinduism/book/the-bhagavata-purana', 135),
  ('purana:bhagavata:vamana-bali', 'purana', 'Bhagavata Purana', 'Canto 8, Chapters 15–22', 'Three paces of land from King Bali', 'generosity greater than loss', 'A dwarf brahmin asks the world-conquering Bali for only three paces of land. Warned it is Vishnu himself, Bali gives anyway rather than break his word. Two steps cover all creation; for the third, Bali offers his own head — and is honoured above the gods for it.', 'https://www.wisdomlib.org/hinduism/book/the-bhagavata-purana', 130),
  ('purana:bhagavata:kapila-devahuti', 'purana', 'Bhagavata Purana', 'Canto 3, Chapters 25–33', 'Kapila teaches his mother', 'devotion combined with discernment', 'Devahuti asks her own son for liberating knowledge. Kapila answers that the mind is the cause of both bondage and freedom: attached to the senses it binds, turned toward the divine it frees. He gives her devotion as the gentlest and surest of all methods.', 'https://www.wisdomlib.org/hinduism/book/the-bhagavata-purana', 110),
  ('purana:bhagavata:kunti-prayers', 'purana', 'Bhagavata Purana', 'Canto 1, Chapter 8', 'Kunti asks for calamities', 'difficulty as remembrance', 'As Krishna departs, Queen Kunti prays for misfortune to keep visiting her — because in comfort she forgets him, and in trouble she remembers. It is one of the strangest and most honest prayers in all scripture.', 'https://www.wisdomlib.org/hinduism/book/the-bhagavata-purana', 125),
  ('purana:bhagavata:bhishma-departure', 'purana', 'Bhagavata Purana', 'Canto 1, Chapter 9', 'Bhishma choosing his hour', 'meeting death consciously', 'Lying on a bed of arrows, Bhishma waits for the auspicious northern course of the sun before releasing his life, teaching dharma to the Pandavas until his final breath. He dies with his eyes on Krishna, awake to the last moment.', 'https://www.wisdomlib.org/hinduism/book/the-bhagavata-purana', 110),
  ('purana:bhagavata:dhruva-return', 'purana', 'Bhagavata Purana', 'Canto 4, Chapters 8–12', 'Dhruva''s regret at getting what he asked for', 'asking too little of life', 'Dhruva attains the vision of the Lord and is immediately ashamed: he had performed such austerity merely to ask for a throne. He says he searched for broken glass and found a jewel. The Bhagavata''s lesson is not that he failed, but that we routinely aim too low.', 'https://www.wisdomlib.org/hinduism/book/the-bhagavata-purana', 120),
  ('purana:bhagavata:rishabha-teaching', 'purana', 'Bhagavata Purana', 'Canto 5, Chapter 5', 'Rishabha on what the body is for', 'purpose of human birth', 'Rishabhadeva tells his hundred sons that the human body is not meant for the pursuit of pleasures available to any animal, but for the discipline that purifies. The rare thing about a human birth is that it can be used for something other than appetite.', 'https://www.wisdomlib.org/hinduism/book/the-bhagavata-purana', 115),
  ('purana:bhagavata:churning-ocean', 'purana', 'Bhagavata Purana', 'Canto 8, Chapters 5–9', 'The poison comes before the nectar', 'enduring the bitter phase', 'When the ocean is churned for the nectar of immortality, the first thing to surface is halahala, a poison that threatens all creation. Shiva drinks it and holds it in his throat. Only after the poison is faced does the nectar appear.', 'https://www.wisdomlib.org/hinduism/book/the-bhagavata-purana', 135),
  ('purana:bhagavata:uddhava-gita', 'purana', 'Bhagavata Purana', 'Canto 11, Chapters 6–29', 'Krishna''s last teaching to Uddhava', 'equanimity and letting go', 'Before departing the world, Krishna gives Uddhava his final instruction: see the same self in all beings, keep the mind unshaken by praise or blame, and understand that what is happening is not happening to you. It is the Gita''s quieter, more personal sequel.', 'https://www.wisdomlib.org/hinduism/book/the-bhagavata-purana', 115),
  ('purana:bhagavata:sudama', 'purana', 'Bhagavata Purana', 'Canto 10, Chapters 80–81', 'Sudama''s handful of flattened rice', 'friendship without transaction', 'A destitute brahmin visits his childhood friend, now a king, carrying only a small bundle of beaten rice and too ashamed to offer it. Krishna takes it from him by force and eats it with delight. Sudama goes home having asked for nothing and finds everything changed.', 'https://www.wisdomlib.org/hinduism/book/the-bhagavata-purana', 130),
  ('purana:bhagavata:narada-past-life', 'purana', 'Bhagavata Purana', 'Canto 1, Chapters 5–6', 'Narada, once a servant boy', 'humble beginnings and holy company', 'Narada tells Vyasa he was born to a maidservant and spent one rainy season serving visiting ascetics. Their leftover food and their conversation were enough to change the direction of his soul across lifetimes. Good company, he says, did what nothing else could.', 'https://www.wisdomlib.org/hinduism/book/the-bhagavata-purana', 110),
  ('purana:shiva:markandeya', 'purana', 'Shiva Purana', 'Rudra Samhita', 'Markandeya, the boy who outlived his death', 'refuge and fearlessness', 'Granted a brilliant life of only sixteen years, Markandeya spends his last day clinging to the Shiva linga. When Yama''s noose falls it catches the linga too, and Shiva emerges to stop death itself. The boy is granted deathlessness at the precise moment he had accepted dying.', 'https://www.wisdomlib.org/hinduism/book/shiva-purana-english', 130),
  ('purana:shiva:neelkantha', 'purana', 'Shiva Purana', 'Rudra Samhita, Sati Khanda', 'Neelkantha: holding the poison in the throat', 'bearing what others cannot', 'Shiva swallows the world-destroying halahala and neither spits it out nor lets it descend into him. Parvati holds his throat, and the poison stays there, turning it blue. Greatness here is not destroying the poison but containing it so no one else is harmed.', 'https://www.wisdomlib.org/hinduism/book/shiva-purana-english', 135),
  ('purana:shiva:daksha-yajna', 'purana', 'Shiva Purana', 'Rudra Samhita, Sati Khanda', 'The sacrifice that insulted a daughter', 'pride and the ruin of ritual', 'Daksha holds a grand sacrifice and pointedly does not invite his daughter Sati''s husband. Sati attends anyway, hears her husband mocked, and gives up her body in the fire. A perfectly performed ritual with contempt at its centre becomes worthless.', 'https://www.wisdomlib.org/hinduism/book/shiva-purana-english', 115),
  ('purana:shiva:lingodbhava', 'purana', 'Shiva Purana', 'Vidyeshvara Samhita', 'The pillar of light neither god could measure', 'the limits of ego and knowledge', 'Brahma and Vishnu argue over who is greater. A column of fire appears with no visible top or bottom, and they agree that whoever finds an end wins. Vishnu returns and admits he could not. Brahma lies — and forfeits his worship for it. Honesty about not knowing is the whole test.', 'https://www.wisdomlib.org/hinduism/book/shiva-purana-english', 125),
  ('purana:shiva:ganesha-birth', 'purana', 'Shiva Purana', 'Rudra Samhita, Kumara Khanda', 'How Ganesha got his head', 'obstacles and new beginnings', 'Parvati forms a boy from the turmeric paste of her own body and posts him at her door. He obeys her instruction so completely that he stops even Shiva — and loses his head for it. Restored with an elephant''s head, he becomes the one worshipped first, before every undertaking.', 'https://www.wisdomlib.org/hinduism/book/shiva-purana-english', 135),
  ('purana:shiva:upamanyu', 'purana', 'Shiva Purana', 'Rudra Samhita', 'Upamanyu and the ocean of milk', 'asking greatly, refusing the small bribe', 'The hungry boy Upamanyu performs austerity for milk. Indra appears in disguise offering it and speaking against Shiva; the boy refuses the gift rather than hear his Lord insulted. Shiva then grants him an ocean of milk that never empties.', 'https://www.wisdomlib.org/hinduism/book/shiva-purana-english', 100),
  ('purana:shiva:bhasmasura', 'purana', 'Shiva Purana', 'Rudra Samhita, Yuddha Khanda', 'Bhasmasura, destroyed by his own boon', 'power without wisdom', 'Granted the power to burn anyone whose head he touches, Bhasmasura immediately turns on the god who gave it. He is undone by being invited to dance, imitating a gesture, and placing his hand on his own head. Unearned power finds its own way back to its owner.', 'https://www.wisdomlib.org/hinduism/book/shiva-purana-english', 120),
  ('purana:shiva:jyotirlinga', 'purana', 'Shiva Purana', 'Kotirudra Samhita', 'The twelve lights across the land', 'sacred geography and pilgrimage', 'The Shiva Purana names twelve jyotirlingas from Somnath in Gujarat to Rameshwaram in the south, each with its own story of a devotee whose need called Shiva to that spot. Together they map devotion across the whole of the subcontinent.', 'https://www.wisdomlib.org/hinduism/book/shiva-purana-english', 115),
  ('purana:shiva:ravana-kailasa', 'purana', 'Shiva Purana', 'Chapters on Ravana', 'The demon who tried to carry off a mountain', 'strength that mistakes itself for entitlement', 'Told he cannot pass, Ravana puts his arms under Kailasa and lifts. A single toe comes down and his hands are trapped for a thousand years. He sings his way out, and is given a boon for the singing rather than the lifting.', 'https://www.wisdomlib.org/hinduism/book/shiva-purana-english', 130),
  ('purana:shiva:kannappa', 'purana', 'Shiva Purana', 'Chapters on devotees', 'The hunter who offered his own eye', 'worship that breaks every rule and is accepted', 'A hunter brings meat he has tasted, water carried in his mouth, and flowers from his hair — everything a priest would call defilement. When the image''s eye bleeds he gouges out his own to replace it, and is stopped mid-way through the second.', 'https://www.wisdomlib.org/hinduism/book/shiva-purana-english', 135),
  ('purana:shiva:ardhanarishvara', 'purana', 'Shiva Purana', 'Chapters on the half-female form', 'One body, split down the middle', 'a wholeness that is not one thing', 'The Purana describes a single form that is male on one side and female on the other, down to the earring and the anklet. It is the tradition''s most direct statement that neither half is complete on its own.', 'https://www.wisdomlib.org/hinduism/book/shiva-purana-english', 125),
  ('purana:shiva:moon-waning', 'purana', 'Shiva Purana', 'Chapters on the moon', 'The curse that was only half lifted', 'a punishment softened rather than cancelled', 'Cursed to waste away for neglecting all but one of his wives, the moon is not simply forgiven. The curse is halved: he wanes for a fortnight and recovers for a fortnight, for ever. The sky still shows the sentence being served.', 'https://www.wisdomlib.org/hinduism/book/shiva-purana-english', 130),
  ('purana:markandeya:mahishasura', 'purana', 'Markandeya Purana', 'Devi Mahatmya, Chapters 2–4', 'Durga and the buffalo demon', 'the strength that rises when all else fails', 'No single god can defeat Mahishasura, so all of them release their energies at once and a goddess forms from the combined light — each weapon in her many hands a gift from one of them. What none could do alone, their united power accomplishes as her.', 'https://www.wisdomlib.org/hinduism/book/the-markandeya-purana', 135),
  ('purana:markandeya:madhu-kaitabha', 'purana', 'Markandeya Purana', 'Devi Mahatmya, Chapter 1', 'The sleep that had to be woken', 'awakening from delusion', 'Two demons born of Vishnu''s cosmic sleep threaten Brahma, who cannot wake the Lord. He praises Yoganidra, the goddess of that sleep, and only when she withdraws does Vishnu stir. The obstacle and the solution are the same power, facing two directions.', 'https://www.wisdomlib.org/hinduism/book/the-markandeya-purana', 105),
  ('purana:markandeya:shumbha-nishumbha', 'purana', 'Markandeya Purana', 'Devi Mahatmya, Chapters 5–10', 'Alone against Shumbha and Nishumbha', 'facing the many with the one', 'Taunted for fighting with help, the Devi withdraws every emanation back into herself and says: see, I am alone in the world — who else is there? She then defeats the demons single-handed. The many powers were never separate from the one.', 'https://www.wisdomlib.org/hinduism/book/the-markandeya-purana', 115),
  ('purana:markandeya:harishchandra', 'purana', 'Markandeya Purana', 'Chapters 7–8', 'Harishchandra, who would not tell one lie', 'truth held past all reason', 'To keep a promise, a king gives away his kingdom, sells his wife and son, and takes work at a cremation ground. Tested at the lowest possible moment — asked for a fee to burn his own child — he still will not break his word.', 'https://www.wisdomlib.org/hinduism/book/the-markandeya-purana', 125),
  ('purana:markandeya:madalasa', 'purana', 'Markandeya Purana', 'Chapters 25–27', 'Madalasa''s lullaby', 'raising children in wisdom', 'Queen Madalasa sings her infants to sleep with ''you are pure, you are awake, you are without form'' — refusing to soothe them with flattery about the body. Three sons renounce the world; the fourth she is asked to raise as a king, and she teaches him to rule as one.', 'https://www.wisdomlib.org/hinduism/book/the-markandeya-purana', 110),
  ('purana:markandeya:dharma-birds', 'purana', 'Markandeya Purana', 'Opening chapters — the four birds', 'Four birds who remembered being men', 'wisdom from an unlikely mouth', 'The Purana''s questions are not answered by a sage but by four birds in a cave, who recall their previous births and speak the whole book. The tradition put its teaching in the mouths of animals and expected it to be taken seriously.', 'https://www.wisdomlib.org/hinduism/book/the-markandeya-purana', 120),
  ('purana:markandeya:suratha-samadhi', 'purana', 'Markandeya Purana', 'Devi Mahatmya — the frame', 'A king and a merchant, both thrown out', 'attachment surviving the thing it attached to', 'A king who has lost his kingdom and a merchant thrown out by his own family meet in a forest, and each admits he still worries about the people who ruined him. The whole Devi Mahatmya is told to explain why they cannot stop.', 'https://www.wisdomlib.org/hinduism/book/the-markandeya-purana', 130),
  ('purana:markandeya:sanjna', 'purana', 'Markandeya Purana', 'Chapters on the sun', 'The wife who could not bear his brightness', 'love that has to be made survivable', 'Unable to stand her husband''s heat, Sanjna leaves a shadow of herself in her place and runs. When the sun finds her, he agrees to be ground down on a wheel until he is bearable. Something is cut away so the marriage can continue.', 'https://www.wisdomlib.org/hinduism/book/the-markandeya-purana', 130),
  ('purana:markandeya:dattatreya', 'purana', 'Markandeya Purana', 'Chapters on Dattatreya', 'The teacher who behaved badly on purpose', 'a test disguised as disappointment', 'Dattatreya drives away followers by drinking, keeping bad company and refusing to look holy. Those who stay anyway are the ones he teaches. The disqualifying behaviour is the entrance examination.', 'https://www.wisdomlib.org/hinduism/book/the-markandeya-purana', 125),
  ('purana:markandeya:anasuya', 'purana', 'Markandeya Purana', 'Chapters on Anasuya', 'Three gods who came to test a woman', 'a test answered on the tester''s own terms', 'Three gods arrive in disguise and demand to be fed by a woman wearing nothing. She agrees, and turns them into infants first. They are fed, and they leave having lost the argument entirely.', 'https://www.wisdomlib.org/hinduism/book/the-markandeya-purana', 130),
  ('purana:markandeya:alarka', 'purana', 'Markandeya Purana', 'Chapters on King Alarka', 'The king whose brother took everything', 'being freed by losing', 'Alarka, raised in comfort, is stripped of his kingdom by his own brother at his mother''s arranging. Only with nothing left does he go and ask the question he had never needed to ask. The dispossession was the instruction.', 'https://www.wisdomlib.org/hinduism/book/the-markandeya-purana', 125),
  ('purana:markandeya:yama-worlds', 'purana', 'Markandeya Purana', 'Chapters on the afterlife', 'The accounting, described to a bird', 'consequence explained plainly', 'The Purana''s account of what follows death is delivered in the same level voice as its geography and its dynasties. There is no relish in it, which makes it harder to dismiss than a sermon would be.', 'https://www.wisdomlib.org/hinduism/book/the-markandeya-purana', 110),
  ('purana:garuda:soul-journey', 'purana', 'Garuda Purana', 'Preta Khanda', 'What the Garuda Purana says about after', 'mortality and accountability', 'Recited traditionally in the days after a death, this section describes the soul''s passage and the consequences of a life''s actions. Its actual purpose is addressed to the living: it is a book about how to act now, delivered in the one moment people truly listen.', 'https://www.wisdomlib.org/hinduism/book/the-garuda-purana', 115),
  ('purana:garuda:charity', 'purana', 'Garuda Purana', 'Acara Khanda', 'What actually travels with you', 'detachment from possessions', 'The Garuda Purana states plainly that wealth stays behind, relatives turn back at the door, and only what a person has done accompanies them. It urges giving while living rather than leaving it to others afterwards.', 'https://www.wisdomlib.org/hinduism/book/the-garuda-purana', 120),
  ('purana:garuda:right-living', 'purana', 'Garuda Purana', 'Acara Khanda', 'The habits that quietly decide a life', 'daily discipline', 'Between its cosmology the Garuda Purana gives ordinary instruction: rise early, eat moderately, speak without cruelty, keep good company, and do not postpone dharma to old age. It treats routine as destiny in slow motion.', 'https://www.wisdomlib.org/hinduism/book/the-garuda-purana', 105),
  ('purana:garuda:mother-in-bondage', 'purana', 'Garuda Purana', 'Purva Khanda — the birth of Garuda', 'The bet his mother lost', 'inheriting somebody else''s mistake', 'Vinata wagers on the colour of a horse''s tail, is cheated, and becomes a slave to her sister for it. Garuda is born into that servitude, having agreed to nothing. Everything he does afterwards is about a debt he did not incur.', 'https://www.wisdomlib.org/hinduism/book/the-garuda-purana', 130),
  ('purana:garuda:stealing-nectar', 'purana', 'Garuda Purana', 'Purva Khanda — the theft of the amrita', 'He carried it and never drank it', 'power used entirely for someone else', 'Garuda fights through fire, a spinning blade and the assembled gods to reach the nectar of immortality, carries it out, and does not taste a drop. It was the price of his mother''s freedom and nothing more.', 'https://www.wisdomlib.org/hinduism/book/the-garuda-purana', 135),
  ('purana:garuda:wings-and-service', 'purana', 'Garuda Purana', 'Purva Khanda', 'The strongest thing alive, agreeing to carry someone', 'strength that chooses to be under someone', 'Having beaten everyone, Garuda accepts a position: he becomes the one Vishnu rides. The Purana treats the choice as the point of the whole story, not as an anticlimax after it.', 'https://www.wisdomlib.org/hinduism/book/the-garuda-purana', 125),
  ('purana:garuda:yama-messengers', 'purana', 'Garuda Purana', 'Preta Khanda', 'The ones who come at the end, and who they wait for', 'an arrival nobody schedules', 'The Purana describes the messengers of death arriving for one person and turning back from another, and is specific that the difference is not wealth, learning or the size of the funeral being planned.', 'https://www.wisdomlib.org/hinduism/book/the-garuda-purana', 125),
  ('purana:garuda:pinda', 'purana', 'Garuda Purana', 'Preta Khanda — the rites', 'Ten days of building a body', 'grief given something to do', 'The rites after a death are described as constructing a new body for the departed, one part per day, over ten days. Whatever else it is, it is a structure that gives a shattered household a task each morning.', 'https://www.wisdomlib.org/hinduism/book/the-garuda-purana', 120),
  ('purana:garuda:gems', 'purana', 'Garuda Purana', 'Purva Khanda — chapters on gemstones', 'How to tell a real stone from a good fake', 'the tests that separate the genuine from the convincing', 'The Purana sets out how each gem is formed, where it is found and how it is tested — hardness, colour under water, behaviour in the light. It is a chapter about not being fooled, sitting inside a book about death.', 'https://www.wisdomlib.org/hinduism/book/the-garuda-purana', 105),
  ('purana:garuda:medicine', 'purana', 'Garuda Purana', 'Purva Khanda — chapters on treatment', 'Remedies in a book about dying', 'fighting for a life while describing its end', 'The same text famous for its account of the afterlife spends long chapters on cures, dosages and the treatment of poisons. It does not treat the two as being in tension.', 'https://www.wisdomlib.org/hinduism/book/the-garuda-purana', 100),
  ('purana:garuda:thousand-names', 'purana', 'Garuda Purana', 'Purva Khanda', 'A thousand ways of saying one name', 'repetition that is not repetitive', 'The Purana carries a thousand-name litany, each name a different quality of the same being. Recited straight through, it is an argument that no single description would have been enough.', 'https://www.wisdomlib.org/hinduism/book/the-garuda-purana', 105),
  ('purana:garuda:moksha', 'purana', 'Garuda Purana', 'Brahma Khanda', 'The chapters people stop reading before', 'the answer after the frightening part', 'The Garuda Purana is known almost entirely for its hells, which come before its final section on liberation. The book''s own structure puts the fear first and the way out last, and most readers never reach the last.', 'https://www.wisdomlib.org/hinduism/book/the-garuda-purana', 125),
  ('purana:skanda:kartikeya-birth', 'purana', 'Skanda Purana', 'Maheshvara Khanda', 'The child born to end Taraka', 'courage arriving when needed', 'Tarakasura''s boon makes him unkillable except by a son of Shiva — and Shiva is deep in meditation with no interest in marriage. The whole story is the universe patiently arranging the conditions for the one being who can end the tyranny.', 'https://www.wisdomlib.org/hinduism/book/the-skanda-purana', 110),
  ('purana:skanda:kashi', 'purana', 'Skanda Purana', 'Kashi Khanda', 'The city that is never destroyed', 'sacred space and liberation', 'Kashi is described as resting on Shiva''s trident, untouched even by the dissolution that ends the worlds. Its promise is not comfort but liberation: to die there is to be released, which is why the old and the dying still travel to it.', 'https://www.wisdomlib.org/hinduism/book/the-skanda-purana', 115),
  ('purana:skanda:shiva-parvati-marriage', 'purana', 'Skanda Purana', 'Maheshvara Khanda', 'Parvati''s austerity for a beggar''s hand', 'steadfast love and inner worth', 'Parvati abandons palace life for severe penance to win an ascetic who owns nothing. Shiva comes disguised as an old man to argue his own case badly, listing his faults. She refuses to be talked out of it, and he reveals himself.', 'https://www.wisdomlib.org/hinduism/book/the-skanda-purana', 125),
  ('purana:skanda:satyanarayana', 'purana', 'Skanda Purana', 'Reva Khanda — the Satyanarayana story', 'The merchant who kept forgetting his promise', 'gratitude that lapses the moment things improve', 'A trader vows an offering if his fortunes turn, gets everything he asked for, and does not perform it. He loses it all again, promises again, forgets again. The story is told and retold in households precisely because nobody in it learns quickly.', 'https://www.wisdomlib.org/hinduism/book/the-skanda-purana', 135),
  ('purana:skanda:mango-contest', 'purana', 'Skanda Purana', 'Chapters on Kartikeya', 'Two brothers, one fruit, one shortcut', 'cleverness beating effort, and the resentment after', 'Told the fruit goes to whoever circles the world first, one brother sets off and the other walks around his parents and claims it. The Purana does not treat the winner as simply right: the loser leaves home over it and does not come back.', 'https://www.wisdomlib.org/hinduism/book/the-skanda-purana', 130),
  ('purana:skanda:krittikas', 'purana', 'Skanda Purana', 'Chapters on the birth of Skanda', 'Six mothers for one child', 'being raised by more people than gave birth to you', 'The child is carried by fire, by the Ganga, and finally by six stars who each nurse him, which is why he is given six faces. The Purana''s account of a divine birth is mostly an account of who did the work afterwards.', 'https://www.wisdomlib.org/hinduism/book/the-skanda-purana', 120),
  ('purana:skanda:taraka-fall', 'purana', 'Skanda Purana', 'Chapters on the war with Taraka', 'The general who was six days old', 'readiness that has nothing to do with age', 'The army of the gods, defeated for generations, is handed to a newborn. The Purana lingers on the moment the veterans have to take orders from him, and on the fact that they win.', 'https://www.wisdomlib.org/hinduism/book/the-skanda-purana', 125),
  ('purana:skanda:palani', 'purana', 'Skanda Purana', 'Chapters on Kartikeya', 'The god who left home in a temper', 'a family quarrel that never quite heals', 'Cheated of the fruit, Kartikeya renounces everything, walks to a bare hill and stays there as an ascetic. His parents follow to bring him back. He does not return with them, and the hill becomes the shrine.', 'https://www.wisdomlib.org/hinduism/book/the-skanda-purana', 125),
  ('purana:skanda:mahakala', 'purana', 'Skanda Purana', 'Avanti Khanda', 'The lord of time, at Ujjain', 'the one thing that outlasts every deadline', 'At Ujjain, Shiva is worshipped specifically as time itself. The Purana''s point in naming him so is uncomfortable and deliberate: the thing everyone is running out of is the thing being worshipped.', 'https://www.wisdomlib.org/hinduism/book/the-skanda-purana', 120),
  ('purana:skanda:badari', 'purana', 'Skanda Purana', 'Vaishnava Khanda — Badarikashrama', 'The shrine that is buried half the year', 'devotion arranged around what is possible', 'The Purana describes a place in the high mountains that snow closes for six months. Rather than claim it is always open, the tradition built a calendar around the closing and the reopening.', 'https://www.wisdomlib.org/hinduism/book/the-skanda-purana', 110),
  ('purana:skanda:nagara-well', 'purana', 'Skanda Purana', 'Nagara Khanda', 'The town that wrote down its own founding', 'a community keeping its own record', 'One entire division of the Purana is given over to a single town''s shrines, families and origin story. It is scripture doing the work of a local history, written by people who did not expect anyone else to do it.', 'https://www.wisdomlib.org/hinduism/book/the-skanda-purana', 95),
  ('purana:skanda:longest-purana', 'purana', 'Skanda Purana', 'The text as a whole', 'The book nobody has read all of', 'a work larger than any one reader', 'The Skanda Purana is the longest of the eighteen by a wide margin, assembled in khandas over centuries by many hands. It is less a book than a shelf, and the tradition kept adding to it rather than closing it.', 'https://www.wisdomlib.org/hinduism/book/the-skanda-purana', 100),
  ('purana:padma:bhakti-sons', 'purana', 'Padma Purana', 'Uttara Khanda, Bhagavata Mahatmya', 'Devotion young, her sons grown old', 'feeling without dryness', 'Narada meets a young woman named Bhakti tending two exhausted old men, Jnana and Vairagya — knowledge and dispassion. Devotion stays young wherever she goes, but her sons age in a world that keeps only the theory and loses the love.', 'https://www.wisdomlib.org/hinduism/book/the-padma-purana', 120),
  ('purana:padma:tulsi', 'purana', 'Padma Purana', 'Uttara Khanda', 'Why tulsi stands in the courtyard', 'faithfulness and the sacred ordinary', 'The story of Vrinda, whose devotion protected her husband so completely that it had to be undone by a divine deception, ends with her becoming the tulsi plant. An offering to Vishnu is considered incomplete without her leaf — the wronged one placed permanently above the ritual.', 'https://www.wisdomlib.org/hinduism/book/the-padma-purana', 115),
  ('purana:padma:ekadashi', 'purana', 'Padma Purana', 'Uttara Khanda', 'The fast that began as a weapon', 'restraint and its rewards', 'The Padma Purana traces the origin of Ekadashi to a personified power born to defeat a demon that could not be beaten by force. The practice is presented as a monthly discipline of the appetite that clears the mind more than it empties the stomach.', 'https://www.wisdomlib.org/hinduism/book/the-padma-purana', 110),
  ('purana:padma:lotus-creation', 'purana', 'Padma Purana', 'Srishti Khanda', 'The flower the world was made on', 'beginning from something that grew, not something built', 'The Purana takes its name from a lotus rising out of the navel of a sleeping god, with the creator seated in it. Everything that follows rests on a flower on a stalk on a body that is not awake.', 'https://www.wisdomlib.org/hinduism/book/the-padma-purana', 115),
  ('purana:padma:pushkar', 'purana', 'Padma Purana', 'Srishti Khanda — Pushkara Mahatmya', 'The one place the creator is worshipped', 'being remembered in a single spot', 'Of all the gods, Brahma has effectively one temple, at a lake said to have formed where a lotus fell from his hand. The Purana''s long defence of the site is also an admission of how little else there is.', 'https://www.wisdomlib.org/hinduism/book/the-padma-purana', 110),
  ('purana:padma:bhrigu-test', 'purana', 'Padma Purana', 'Uttara Khanda', 'The sage who kicked a god in the chest', 'an insult answered by concern', 'Sent to find out which god is greatest, Bhrigu provokes each in turn and finally kicks the sleeping Vishnu. Vishnu wakes, takes the foot in both hands and asks whether it was hurt. The test ends there.', 'https://www.wisdomlib.org/hinduism/book/the-padma-purana', 135),
  ('purana:padma:rama-in-patala', 'purana', 'Padma Purana', 'Patala Khanda', 'What happened after the story ended', 'the years nobody makes songs about', 'The Padma Purana picks Rama up after the coronation, in the long reign where there is no demon to fight and every decision costs him something private. It is the least dramatic part of his life and the Purana gives it the most room.', 'https://www.wisdomlib.org/hinduism/book/the-padma-purana', 125),
  ('purana:padma:gita-mahatmya', 'purana', 'Padma Purana', 'Uttara Khanda — the greatness of the Gita', 'A book praised chapter by chapter', 'a text the tradition kept insisting on', 'The Purana works through the Gita one chapter at a time, telling a story about somebody whose life was changed by each. It is the tradition arguing, at length, that this particular book should not be left unread.', 'https://www.wisdomlib.org/hinduism/book/the-padma-purana', 105),
  ('purana:padma:kartika', 'purana', 'Padma Purana', 'Uttara Khanda — Kartika Mahatmya', 'The month of small lamps', 'practice concentrated into a season', 'For one month the Purana asks for very little each day — a lamp, a bath before dawn, a name said aloud — and claims the accumulation matters more than any single large act performed once.', 'https://www.wisdomlib.org/hinduism/book/the-padma-purana', 110),
  ('purana:padma:svarga-is-temporary', 'purana', 'Padma Purana', 'Svarga Khanda', 'Heaven runs out', 'a reward that is spent like money', 'The Purana describes the heavens in detail and then says plainly that residence there lasts exactly as long as the merit that paid for it, after which the resident falls. Nothing gained by good deeds is permanent.', 'https://www.wisdomlib.org/hinduism/book/the-padma-purana', 125),
  ('purana:padma:yamuna', 'purana', 'Padma Purana', 'Bhumi Khanda', 'The dark river and the bright one', 'two ways of being holy', 'The Purana sets the Yamuna beside the Ganga and does not rank them. One is described as purifying and the other as loving, and it treats the difference as a difference in temperament rather than in worth.', 'https://www.wisdomlib.org/hinduism/book/the-padma-purana', 105),
  ('purana:padma:one-god-argument', 'purana', 'Padma Purana', 'Uttara Khanda', 'The quarrel the text tries to end', 'sectarian argument seen from above', 'The Purana repeatedly stages the Shiva-versus-Vishnu argument and repeatedly has one of the two refuse it, usually by praising the other first. The device is used often enough to count as the book''s own position.', 'https://www.wisdomlib.org/hinduism/book/the-padma-purana', 110),
  ('purana:linga:formless-form', 'purana', 'Linga Purana', 'Purva Bhaga', 'Worshipping the mark, not the shape', 'the formless behind the form', 'The Linga Purana explains the linga as a ''mark'' or sign — a deliberately unshaped form for what has no shape, so that the mind has somewhere to rest without mistaking the image for the reality it points at.', 'https://www.wisdomlib.org/hinduism/book/the-linga-purana', 105),
  ('purana:linga:nandi', 'purana', 'Linga Purana', 'Purva Bhaga', 'Nandi, waiting at the door', 'patience and steady attention', 'The bull who sits before every Shiva shrine faces the sanctum and never looks away. He is the model of the devotee: not performing, not asking, simply keeping his gaze fixed in the right direction for as long as it takes.', 'https://www.wisdomlib.org/hinduism/book/the-linga-purana', 105),
  ('purana:linga:five-faces', 'purana', 'Linga Purana', 'Purva Bhaga — the five faces', 'Five faces, and one of them turned away', 'a whole that includes what you would rather not see', 'Shiva is described with five faces looking in five directions — the gentle one, the beautiful one, the one that creates, the one that conceals, and Aghora, the terrible one facing south. The Purana does not offer the pleasant four without the fifth.', 'https://www.wisdomlib.org/hinduism/book/the-linga-purana', 120),
  ('purana:linga:tripura', 'purana', 'Linga Purana', 'Uttara Bhaga — the burning of the three cities', 'Three cities, one arrow, one moment', 'patience waiting for the single opening', 'Three flying fortresses of gold, silver and iron are protected by a boon: they can only be destroyed when all three align, by a single arrow. Shiva waits, with the earth as his chariot and the Vedas as his horses, for the instant they cross — and takes it.', 'https://www.wisdomlib.org/hinduism/book/the-linga-purana', 125),
  ('purana:linga:kamadahana', 'purana', 'Linga Purana', 'Purva Bhaga — the burning of Kama', 'The god of desire, burnt to ash', 'desire interrupted, and what survives it', 'Sent to break Shiva''s meditation with a flower arrow, Kama succeeds for an instant and is burnt to ash by the opening of the third eye. His wife Rati is left with nothing to bury. Kama is restored, but bodiless — desire that can still be felt and no longer seen.', 'https://www.wisdomlib.org/hinduism/book/the-linga-purana', 125),
  ('purana:linga:tandava', 'purana', 'Linga Purana', 'Uttara Bhaga — the dance', 'The dance that is holding the world together', 'order that depends on continuous effort', 'Creation is not described as a thing built and left standing. It is described as a dance still going on, and the Purana is explicit that the world lasts exactly as long as the dancer keeps moving.', 'https://www.wisdomlib.org/hinduism/book/the-linga-purana', 120),
  ('purana:linga:jalandhara', 'purana', 'Linga Purana', 'Uttara Bhaga — Jalandhara', 'The warrior born from Shiva''s own anger', 'a thing that turns on the one who made it', 'Jalandhara is formed from fire that came out of Shiva''s own eyes, grows into the strongest being alive, and eventually comes for Shiva. The Purana is unsentimental about the arithmetic: he could not be beaten by anything except the source he came from.', 'https://www.wisdomlib.org/hinduism/book/the-linga-purana', 120),
  ('purana:linga:ashtamurti', 'purana', 'Linga Purana', 'Purva Bhaga — the eight forms', 'Eight things that are all one thing', 'the divine as the ordinary world', 'The Linga Purana names Shiva''s eight forms as earth, water, fire, air, ether, the sun, the moon, and the sacrificer. Nothing is added to the world to make it holy. The list is the world, counted differently.', 'https://www.wisdomlib.org/hinduism/book/the-linga-purana', 105),
  ('purana:linga:andhaka', 'purana', 'Linga Purana', 'Purva Bhaga — Andhaka', 'The enemy who became the doorkeeper', 'an opponent turned rather than destroyed', 'Andhaka, born blind and raised in demonic power, comes for Parvati and is defeated. He is not annihilated. Held aloft on Shiva''s trident until his pride burns away, he is set down as a devotee and given a place among Shiva''s own attendants.', 'https://www.wisdomlib.org/hinduism/book/the-linga-purana', 110),
  ('purana:linga:daruka-forest', 'purana', 'Linga Purana', 'Uttara Bhaga — the sages of the Daruka forest', 'The sages who were sure of themselves', 'learning without humility', 'A colony of accomplished sages in the Daruka forest are certain their rituals have made them masters. Shiva walks in as a naked beggar and undoes their certainty without argument. Their curses fail against him, and the failure is the teaching.', 'https://www.wisdomlib.org/hinduism/book/the-linga-purana', 110),
  ('purana:linga:ganga-descent', 'purana', 'Linga Purana', 'Uttara Bhaga — the descent of Ganga', 'The river that would have split the earth', 'a force that has to be received before it can be used', 'Bhagiratha''s austerity brings the Ganga down from heaven, but her fall would break the ground she is meant to bless. Shiva stands under it and takes the whole weight of the river in his matted hair, letting it out slowly enough for the earth to hold.', 'https://www.wisdomlib.org/hinduism/book/the-linga-purana', 125),
  ('purana:linga:twenty-eight-teachers', 'purana', 'Linga Purana', 'Uttara Bhaga — the twenty-eight incarnations', 'The teacher who came back twenty-eight times', 'instruction repeated until it takes', 'The Linga Purana lists twenty-eight descents of Shiva as a teacher of yoga, one for each age, each with his own disciples. The tradition''s own account of itself is not a single revelation but a thing taught again whenever it is forgotten.', 'https://www.wisdomlib.org/hinduism/book/the-linga-purana', 100),
  ('purana:brahma:surya-worship', 'purana', 'Brahma Purana', 'Chapters on Konarka', 'Samba and the healing sun', 'humility and healing', 'Afflicted with disease after a curse, Samba worships the sun at the shore and is cured, founding the temple at Konark. The Brahma Purana links sunlight, discipline and recovery — the oldest medicine being to rise and face the light.', 'https://www.wisdomlib.org/hinduism/book/the-brahma-purana', 100),
  ('purana:brahma:jagannath', 'purana', 'Brahma Purana', 'Purushottama Kshetra Mahatmya', 'The unfinished form at Puri', 'accepting the incomplete', 'The images at Puri are famously unfinished — the sculptor was interrupted before the hands and feet were carved. They were installed exactly as they were, and are worshipped in that state by millions. Not everything sacred has to be completed first.', 'https://www.wisdomlib.org/hinduism/book/the-brahma-purana', 115),
  ('purana:brahma:gautama-godavari', 'purana', 'Brahma Purana', 'Gautami Mahatmya', 'The sage who was tricked into a blessing', 'a wrong turned into a gift for everyone', 'During a famine, only Gautama''s hermitage has grain, and the jealous sages send an illusory cow into his field so he will appear to have killed it. Framed and shamed, Gautama does not retaliate. He performs austerity until the Godavari comes down to wash the ground, and the river stays for everyone who framed him.', 'https://www.wisdomlib.org/hinduism/book/the-brahma-purana', 125),
  ('purana:brahma:ekamra', 'purana', 'Brahma Purana', 'Ekamra Kshetra Mahatmya', 'The field under one mango tree', 'a place made sacred by presence, not by size', 'The Brahma Purana describes Ekamra, the single-mango-tree field, as the ground Shiva chose over grander places. Its holiness has no monument behind it and no conquest — the text''s claim is simply that he stayed there.', 'https://www.wisdomlib.org/hinduism/book/the-brahma-purana', 100),
  ('purana:brahma:yama-court', 'purana', 'Brahma Purana', 'Chapters on Yama and the afterlife', 'What is actually written down', 'an account nobody else is keeping', 'The Brahma Purana''s account of Yama''s court is not primarily about punishment. It is about record: that what a person did when nobody was looking was nevertheless noted, and that the ledger is read out in their own hearing.', 'https://www.wisdomlib.org/hinduism/book/the-brahma-purana', 110),
  ('purana:brahma:creation-order', 'purana', 'Brahma Purana', 'Opening chapters on creation', 'The world made in an order', 'beginnings that are deliberate', 'The Purana opens with Brahma bringing forth the elements, the directions, time itself, and only then living beings — each depending on what came before it. Nothing arrives fully formed, and the sequence is the point.', 'https://www.wisdomlib.org/hinduism/book/the-brahma-purana', 95),
  ('purana:brahma:shiva-parvati-marriage', 'purana', 'Brahma Purana', 'Chapters on the marriage of Shiva and Parvati', 'The ascetic who was talked into a household', 'persistence outlasting refusal', 'Parvati sets out to marry a man who has renounced marriage, and is refused by his own silence for years. She does not argue with him. She takes up the same austerity he is famous for, until the difference between them is gone.', 'https://www.wisdomlib.org/hinduism/book/the-brahma-purana', 125),
  ('purana:brahma:krishna-childhood', 'purana', 'Brahma Purana', 'Krishna chapters', 'The god who was somebody''s difficult child', 'greatness hidden inside the ordinary', 'The Brahma Purana''s Krishna chapters keep him small: stealing butter, being tied to a mortar, being scolded. The claim underneath is that the same being who holds the worlds spent years being told off by a woman who thought he was hers.', 'https://www.wisdomlib.org/hinduism/book/the-brahma-purana', 130),
  ('purana:brahma:sun-course', 'purana', 'Brahma Purana', 'Chapters on the sun''s course', 'The chariot that never stops', 'reliability as a form of devotion', 'The sun''s daily circuit is described as a chariot with one wheel, seven horses and a driver with no legs, none of which is an accident of ornament. What the Purana emphasises is that it has never once failed to arrive.', 'https://www.wisdomlib.org/hinduism/book/the-brahma-purana', 95),
  ('purana:brahma:four-ages', 'purana', 'Brahma Purana', 'Chapters on the yugas', 'The ages, and which one this is', 'living in a diminished time', 'The four ages are described in decline: dharma standing on four legs, then three, then two, then one. The Purana does not treat the last age as hopeless. It treats it as the age in which very little is required to stand out.', 'https://www.wisdomlib.org/hinduism/book/the-brahma-purana', 105),
  ('purana:brahma:pitris', 'purana', 'Brahma Purana', 'Chapters on shraddha', 'What the dead are owed', 'obligation that does not end at a funeral', 'The rites for ancestors are described not as mourning but as maintenance — a debt carried by the living, paid at fixed intervals, by people who will one day be on the receiving end of the same attention.', 'https://www.wisdomlib.org/hinduism/book/the-brahma-purana', 100),
  ('purana:brahma:tirtha-worth', 'purana', 'Brahma Purana', 'Gautami Mahatmya', 'The pilgrim who brought himself along', 'travel that changes nothing', 'Between its long lists of holy fords the Purana makes a blunt point: a person who bathes at every one of them and carries the same anger home has washed only his body. The place does not do the work.', 'https://www.wisdomlib.org/hinduism/book/the-brahma-purana', 115),
  ('purana:brahmanda:lalita', 'purana', 'Brahmanda Purana', 'Lalita Mahatmya', 'The thousand names of Lalita', 'the divine feminine as beauty and power', 'The Lalita Sahasranama, preserved in the Brahmanda Purana, praises the goddess as both the ruler of the cosmos and the sweetness within it. Its thousand names insist that power and tenderness are not opposites.', 'https://www.wisdomlib.org/hinduism/book/the-brahmanda-purana', 105),
  ('purana:brahmanda:cosmic-egg', 'purana', 'Brahmanda Purana', 'Prakriya Pada', 'The egg the whole world came out of', 'everything having a single origin', 'The Purana takes its name from its opening image: a golden egg floating in the waters, containing every world, every ocean and every being, which splits to become the sky above and the earth below. Everything that exists was once inside one shell.', 'https://www.wisdomlib.org/hinduism/book/the-brahmanda-purana', 120),
  ('purana:brahmanda:bhandasura', 'purana', 'Brahmanda Purana', 'Lalita Mahatmya', 'The demon made from ashes', 'what grows from something burnt away', 'From the ash of the burnt Kama, a demon is formed who cannot be killed by any god. Bhandasura drains the desire out of the world and rules a joyless kingdom. It takes the Goddess herself, and an army of her own emanations, to end him.', 'https://www.wisdomlib.org/hinduism/book/the-brahmanda-purana', 125),
  ('purana:brahmanda:agastya-hayagriva', 'purana', 'Brahmanda Purana', 'Lalita Mahatmya — the teaching to Agastya', 'The sage who was told to ask properly', 'receiving knowledge on the right terms', 'Agastya asks Hayagriva for the highest knowledge and is refused twice before he is given it, not because it is being withheld but because he has not yet asked as a person who would use it. The thousand names are given only on the third asking.', 'https://www.wisdomlib.org/hinduism/book/the-brahmanda-purana', 110),
  ('purana:brahmanda:parashurama-renuka', 'purana', 'Brahmanda Purana', 'Parashurama chapters', 'The son told to kill his mother', 'obedience that costs everything', 'Jamadagni orders each of his sons to kill their mother Renuka for a moment''s wandering thought. Only Parashurama obeys. Offered any boon for it, he asks for her life back, and for his brothers'' — spending the reward undoing the thing he was rewarded for.', 'https://www.wisdomlib.org/hinduism/book/the-brahmanda-purana', 130),
  ('purana:brahmanda:kartavirya', 'purana', 'Brahmanda Purana', 'Parashurama chapters', 'The king with a thousand arms who took a cow', 'power taking what it does not need', 'Kartavirya Arjuna, a king with a thousand arms and no shortage of anything, takes a sage''s calf simply because he can. The theft costs him his life and his dynasty, and sets Parashurama on a rampage that outlasts everyone who started it.', 'https://www.wisdomlib.org/hinduism/book/the-brahmanda-purana', 125),
  ('purana:brahmanda:agastya-ocean', 'purana', 'Brahmanda Purana', 'Upodghata Pada', 'The sage who drank the sea', 'a hiding place removed', 'Demons hide at the bottom of the ocean by day and destroy by night, and cannot be reached. Agastya drinks the ocean in a single draught, leaving them standing in the open. The Purana notes, drily, that he did not give it back.', 'https://www.wisdomlib.org/hinduism/book/the-brahmanda-purana', 120),
  ('purana:brahmanda:vindhya-bowed', 'purana', 'Brahmanda Purana', 'Upodghata Pada', 'The mountain that is still bowing', 'pride stopped by courtesy rather than force', 'The Vindhya range grows out of jealousy until it blocks the sun. Agastya, its teacher, asks it to bow so he may cross, and to stay that way until he returns. He crosses to the south and never comes back.', 'https://www.wisdomlib.org/hinduism/book/the-brahmanda-purana', 125),
  ('purana:brahmanda:measure-of-time', 'purana', 'Brahmanda Purana', 'Anushanga Pada', 'How long a day of Brahma is', 'a scale that makes a lifetime small', 'The Purana counts time upward from a blink to the four ages, to a thousand of those as one day of Brahma, and then to his hundred years. The arithmetic is not decoration: it is the text making a human worry the right size.', 'https://www.wisdomlib.org/hinduism/book/the-brahmanda-purana', 110),
  ('purana:brahmanda:seven-islands', 'purana', 'Brahmanda Purana', 'Anushanga Pada — geography', 'A map of a world nobody has walked', 'describing the whole before the part', 'Seven island-continents ringed by seven oceans — of salt, of sugarcane juice, of wine, of butter, of curd, of milk, of sweet water — are described in careful order. The tradition insisted on knowing the shape of everything before locating itself in it.', 'https://www.wisdomlib.org/hinduism/book/the-brahmanda-purana', 95),
  ('purana:brahmanda:lalita-city', 'purana', 'Brahmanda Purana', 'Lalita Mahatmya — Sripura', 'The city with twenty-five walls', 'an approach that takes as long as it takes', 'The Goddess''s city is described as ring after ring of walls — iron, bronze, copper, lead, brass, silver, gold, and inward through gemstones to the last chamber. Nobody arrives at the centre quickly, and the description is the instruction.', 'https://www.wisdomlib.org/hinduism/book/the-brahmanda-purana', 105),
  ('purana:brahmanda:royal-lineages', 'purana', 'Brahmanda Purana', 'Upasamhara Pada', 'The kings listed after they are gone', 'how little of a reign survives it', 'The Purana''s dynastic lists name hundreds of rulers, most in a single line each, many with nothing recorded but a name and a father. It is one of the tradition''s plainest statements about how a life looks from far enough away.', 'https://www.wisdomlib.org/hinduism/book/the-brahmanda-purana', 100),
  ('purana:narada:name-chanting', 'purana', 'Narada Purana', 'Purva Bhaga', 'The sage who never stops singing', 'constant remembrance', 'Narada travels between every world carrying his vina and the name, stirring up exactly the trouble that turns people toward the divine. The Narada Purana presents continuous remembrance as the simplest practice available to anyone, anywhere.', 'https://www.wisdomlib.org/hinduism/book/the-narada-purana', 105),
  ('purana:narada:rukmangada', 'purana', 'Narada Purana', 'Uttara Bhaga — Rukmangada Charita', 'The king who would not break a fast', 'a promise held past the point it hurts', 'Rukmangada''s kingdom keeps the Ekadashi fast so faithfully that Yama''s world empties. A woman is sent to break him: she extracts a promise to grant any wish, then asks him to eat on the fast day. He offers her the kingdom, his own life, anything else. She refuses all of it.', 'https://www.wisdomlib.org/hinduism/book/the-narada-purana', 130),
  ('purana:narada:dharmangada', 'purana', 'Narada Purana', 'Uttara Bhaga — Rukmangada Charita', 'The son who offered his own neck', 'a child paying for a parent''s word', 'Cornered between the fast he will not break and the promise he will not break, Rukmangada is asked instead to behead his own son. Dharmangada kneels and tells his father to keep his word. The Purana lets the sword rise before anything intervenes.', 'https://www.wisdomlib.org/hinduism/book/the-narada-purana', 130),
  ('purana:narada:daksha-curse', 'purana', 'Narada Purana', 'Purva Bhaga', 'The sage who talked a thousand sons out of marrying', 'advice that ruins somebody''s plans', 'Narada meets Daksha''s thousand sons on their way to father a race, and asks them what they know about the world they intend to fill. They renounce instead, all of them. Daksha curses him to never rest in one place for long, which is why he is always arriving.', 'https://www.wisdomlib.org/hinduism/book/the-narada-purana', 125),
  ('purana:narada:pride-of-austerity', 'purana', 'Narada Purana', 'Purva Bhaga', 'The one who thought he had conquered desire', 'certainty about oneself as the last weakness', 'Narada comes through an austerity untouched by temptation and goes to announce it. He is warned, gently, not to say it out loud. The Purana''s interest is not in whether he falls but in the exact moment the achievement turned into a claim.', 'https://www.wisdomlib.org/hinduism/book/the-narada-purana', 125),
  ('purana:narada:ekadashi-origin', 'purana', 'Narada Purana', 'Uttara Bhaga — the Ekadashi vratas', 'One day in fourteen', 'a discipline small enough to actually keep', 'The Purana devotes chapter after chapter to a fast that asks for one day out of every fourteen. The scale is the argument: a practice that can be kept by a householder, a labourer and a king alike, and is therefore kept.', 'https://www.wisdomlib.org/hinduism/book/the-narada-purana', 110),
  ('purana:narada:name-over-ritual', 'purana', 'Narada Purana', 'Purva Bhaga', 'What the poor man can afford', 'devotion that costs nothing to begin', 'Against a tradition of expensive sacrifices, the Narada Purana insists the divine name is available to somebody with no priest, no fire, no fee and no learning. It is the most democratic claim the Puranas make, and it is made repeatedly.', 'https://www.wisdomlib.org/hinduism/book/the-narada-purana', 120),
  ('purana:narada:sanaka-teaching', 'purana', 'Narada Purana', 'Purva Bhaga — the teaching of the Kumaras', 'Four boys who never grew up', 'authority that does not come from age', 'The four Kumaras, Brahma''s first sons, refused creation and remained five years old for ever. In the Narada Purana they are the ones doing the teaching, and grown sages sit in front of children to hear it.', 'https://www.wisdomlib.org/hinduism/book/the-narada-purana', 110),
  ('purana:narada:kartika-month', 'purana', 'Narada Purana', 'Uttara Bhaga — the greatness of Kartika', 'The month when a small lamp counts', 'timing that multiplies a modest act', 'The Purana claims a single lamp lit in Kartika is worth more than large gifts in an ordinary month. The reasoning is practical rather than magical: it is the month people are already awake and already gathering.', 'https://www.wisdomlib.org/hinduism/book/the-narada-purana', 105),
  ('purana:narada:tirtha-list', 'purana', 'Narada Purana', 'Uttara Bhaga — the tirthas', 'Every river worth standing in', 'a tradition writing down its own map', 'The Purana catalogues fords, rivers and shrines across the subcontinent with the care of a gazetteer. Read as a whole it is less a devotional text than evidence of how many people were walking, and how far.', 'https://www.wisdomlib.org/hinduism/book/the-narada-purana', 95),
  ('purana:narada:vina', 'purana', 'Narada Purana', 'Purva Bhaga', 'The instrument he never puts down', 'a practice carried everywhere', 'Narada is never described without the vina. He does not stop to play it; he plays while travelling, arguing, warning and interfering. The Purana''s picture of devotion is not a seat and a fixed hour but something carried in the hand all day.', 'https://www.wisdomlib.org/hinduism/book/the-narada-purana', 115),
  ('purana:narada:quarrel-maker', 'purana', 'Narada Purana', 'Purva Bhaga', 'The troublemaker who was always right', 'unwelcome truth delivered at the worst moment', 'Narada has a reputation across the Puranas for starting quarrels, and he earns it. What the Narada Purana points out is that the information he carries is never false. He is disliked for the timing, not the content.', 'https://www.wisdomlib.org/hinduism/book/the-narada-purana', 120),
  ('purana:devi:shakti-supreme', 'purana', 'Devi Bhagavata Purana', 'Book 1 and Book 7', 'Without her, the gods cannot move', 'energy as the ground of everything', 'The Devi Bhagavata places the Goddess as the primal power without which no deity acts at all — consciousness may be still, but nothing happens without shakti. The Devi Gita within it teaches liberation directly in her own voice.', 'https://www.wisdomlib.org/hinduism/book/devi-bhagavata-purana', 115),
  ('purana:agni:everything-book', 'purana', 'Agni Purana', 'Encyclopedic chapters', 'The Purana that teaches everything', 'knowledge in service of living', 'The Agni Purana moves from cosmology to architecture, medicine, grammar, statecraft and archery, then returns to devotion. Its assumption is that practical skill and spiritual life belong in one book, not two.', 'https://www.wisdomlib.org/hinduism/book/the-agni-purana', 100),
  ('purana:agni:vasishtha-taught-by-fire', 'purana', 'Agni Purana', 'Opening chapters', 'The fire that agreed to teach', 'knowledge handed down rather than found', 'The Purana''s frame is Agni himself teaching Vasishtha, who teaches Vyasa, who teaches Suta, who tells it to the assembled sages. Before a word of its content arrives, the text spends its opening on the chain of people who carried it.', 'https://www.wisdomlib.org/hinduism/book/the-agni-purana', 105),
  ('purana:agni:ten-descents', 'purana', 'Agni Purana', 'Chapters on the avataras', 'Ten arrivals, each smaller than expected', 'help that comes in an unimpressive shape', 'The Agni Purana runs through the descents in order — a fish, a tortoise, a boar, a half-lion, a dwarf. The pattern it draws attention to is that the rescue almost never arrives looking like a rescue.', 'https://www.wisdomlib.org/hinduism/book/the-agni-purana', 125),
  ('purana:agni:pratima-lakshana', 'purana', 'Agni Purana', 'Chapters on image-making', 'The rules for carving a god', 'devotion with a measuring rod in hand', 'Proportions, postures, the number of arms, what each hand holds, which way the eyes look: the Purana specifies image-making to the finger''s width. Getting it wrong is treated as a failure of respect, not of craft.', 'https://www.wisdomlib.org/hinduism/book/the-agni-purana', 105),
  ('purana:agni:temple-ground', 'purana', 'Agni Purana', 'Chapters on architecture', 'Testing the soil before building', 'the unglamorous part that decides everything', 'Before any temple is designed, the Purana has the builder dig a pit, refill it, and see whether earth is left over or missing. The instruction for the holiest structure in a town begins with a hole in the ground.', 'https://www.wisdomlib.org/hinduism/book/the-agni-purana', 110),
  ('purana:agni:medicine', 'purana', 'Agni Purana', 'Chapters on medicine', 'A scripture that lists fevers', 'the body as a religious concern', 'Between hymns and cosmology, the Agni Purana sets out diagnoses, herbs and treatments — for people, and for horses and elephants. It does not treat illness as a spiritual failing to be prayed away.', 'https://www.wisdomlib.org/hinduism/book/the-agni-purana', 100),
  ('purana:agni:dhanurveda', 'purana', 'Agni Purana', 'Chapters on archery', 'How to stand before you shoot', 'mastery built from posture upward', 'The archery chapters begin with where to put the feet, how to breathe, and how to hold a bow that is not yet drawn. The arrow is nearly the last thing discussed, which is the whole teaching.', 'https://www.wisdomlib.org/hinduism/book/the-agni-purana', 115),
  ('purana:agni:rajaniti', 'purana', 'Agni Purana', 'Chapters on statecraft', 'Advice for a king who is being lied to', 'power surrounded by flattery', 'The statecraft chapters assume, without embarrassment, that a ruler''s advisors have their own interests and that his information is filtered. The counsel is about how to govern anyway.', 'https://www.wisdomlib.org/hinduism/book/the-agni-purana', 110),
  ('purana:agni:yama-gita', 'purana', 'Agni Purana', 'Yama Gita chapters', 'Death gives the lecture himself', 'instruction from the one who collects', 'In the Yama Gita the god of death sets out what actually matters, on the authority of having seen every life end. The device is deliberate: the argument is unanswerable because of who is making it.', 'https://www.wisdomlib.org/hinduism/book/the-agni-purana', 125),
  ('purana:agni:alankara', 'purana', 'Agni Purana', 'Chapters on poetics', 'The scripture that teaches metaphor', 'saying a thing well as part of saying it truly', 'The Purana includes chapters on figures of speech, metre and dramatic form. A tradition that cared this much about how something is phrased did not regard eloquence as decoration.', 'https://www.wisdomlib.org/hinduism/book/the-agni-purana', 100),
  ('purana:agni:omens', 'purana', 'Agni Purana', 'Chapters on omens and dreams', 'Reading the day before it happens', 'attention to small signs', 'Dreams, bird calls, the direction of the wind and the behaviour of animals are catalogued as things worth noticing. Underneath the divination is a habit the Purana clearly values: looking at what is actually in front of you.', 'https://www.wisdomlib.org/hinduism/book/the-agni-purana', 95),
  ('purana:agni:gita-summary', 'purana', 'Agni Purana', 'Chapters summarising the Gita', 'The whole Gita in a few pages', 'a long teaching reduced to what it needs', 'The Agni Purana compresses the Bhagavad Gita into a handful of chapters. What survives the compression — act, do not sit on the fence, and do not build your peace on the result — is the tradition''s own view of what the Gita is for.', 'https://www.wisdomlib.org/hinduism/book/the-agni-purana', 120),
  ('upanishad:chandogya:tat-tvam-asi', 'upanishad', 'Chandogya Upanishad', 'Chapter 6', 'Tat tvam asi — you are that', 'identity of the self and the absolute', 'Uddalaka has his son dissolve salt in water. It cannot be seen, but every sip is salty. In the same way, he says, the subtle essence pervades everything — and that is what you are. He repeats the phrase nine times so it cannot be missed.', 'https://www.wisdomlib.org/hinduism/book/chandogya-upanishad-english', 135),
  ('upanishad:chandogya:satyakama', 'upanishad', 'Chandogya Upanishad', 'Chapter 4', 'Satyakama, who told the truth about his birth', 'honesty as the true qualification', 'A boy asked his lineage before being accepted as a student repeats his mother''s honest answer: she does not know. The teacher accepts him at once, saying only a brahmin could speak so truthfully. Character, not ancestry, admits him.', 'https://www.wisdomlib.org/hinduism/book/chandogya-upanishad-english', 125),
  ('upanishad:chandogya:seed', 'upanishad', 'Chandogya Upanishad', 'Chapter 6, Section 12', 'Break the seed and find nothing', 'the invisible essence', 'Uddalaka asks Shvetaketu to split a banyan seed, then split what is inside it. The boy reports he sees nothing at all. From that nothing, his father says, this whole great tree stands.', 'https://www.wisdomlib.org/hinduism/book/chandogya-upanishad-english', 125),
  ('upanishad:brihadaranyaka:asato-ma', 'upanishad', 'Brihadaranyaka Upanishad', '1.3.28', 'Lead me from the unreal to the real', 'the prayer for truth and light', 'Asato ma sad gamaya, tamaso ma jyotir gamaya, mrityor ma amritam gamaya — from the unreal to the real, from darkness to light, from death to immortality. Three lines that ask for nothing material at all.', 'https://www.wisdomlib.org/hinduism/book/the-brihadaranyaka-upanishad', 135),
  ('upanishad:brihadaranyaka:maitreyi', 'upanishad', 'Brihadaranyaka Upanishad', '2.4 and 4.5', 'Maitreyi refuses the inheritance', 'what love is actually for', 'Offered half his wealth as he leaves for the forest, Maitreyi asks whether it would make her immortal. Told it would not, she says she has no use for it. Yajnavalkya then tells her that a husband is not loved for the husband''s sake, but for the sake of the Self.', 'https://www.wisdomlib.org/hinduism/book/the-brihadaranyaka-upanishad', 130),
  ('upanishad:brihadaranyaka:neti-neti', 'upanishad', 'Brihadaranyaka Upanishad', '2.3.6 and 4.5.15', 'Neti, neti — not this, not this', 'knowing by removing', 'Asked to describe the Self, Yajnavalkya refuses to say what it is and only says what it is not. Every description would make it a thing among things. The method is subtraction: remove everything you are not and stop.', 'https://www.wisdomlib.org/hinduism/book/the-brihadaranyaka-upanishad', 125),
  ('upanishad:brihadaranyaka:gargi', 'upanishad', 'Brihadaranyaka Upanishad', '3.6 and 3.8', 'Gargi asks one question too many', 'the boundary of enquiry', 'The scholar Gargi presses Yajnavalkya on what everything is woven upon, then on what that is woven upon, until he warns her that her head will fall off if she asks beyond the limit. She stops, then returns with the sharpest question in the assembly.', 'https://www.wisdomlib.org/hinduism/book/the-brihadaranyaka-upanishad', 115),
  ('upanishad:taittiriya:matru-devo-bhava', 'upanishad', 'Taittiriya Upanishad', 'Shiksha Valli, 1.11', 'The graduation speech', 'how to live after learning', 'As students leave, the teacher gives instructions that are entirely practical: speak the truth, practise dharma, do not neglect your studies, treat mother, father, teacher and guest as divine, and give with faith, with modesty, and with sympathy.', 'https://www.wisdomlib.org/hinduism/book/the-taittiriya-upanishad', 130),
  ('upanishad:taittiriya:five-sheaths', 'upanishad', 'Taittiriya Upanishad', 'Brahmananda Valli', 'The five layers of a person', 'depth beneath the surface self', 'The Taittiriya describes a person as sheath within sheath — food, breath, mind, understanding, and bliss — each subtler than the last. What you take yourself to be is usually the outermost one.', 'https://www.wisdomlib.org/hinduism/book/the-taittiriya-upanishad', 115),
  ('upanishad:taittiriya:bhrigu', 'upanishad', 'Taittiriya Upanishad', 'Bhrigu Valli', 'Bhrigu sent back five times', 'answers that must be earned', 'Bhrigu asks his father to explain Brahman. Instead of answering, Varuna gives him a method and sends him away to find out — five times, each time with a deeper answer. The teacher''s restraint is the actual teaching.', 'https://www.wisdomlib.org/hinduism/book/the-taittiriya-upanishad', 110),
  ('ramayana:shabari', 'purana', 'Ramayana of Valmiki', 'Aranya Kanda', 'Shabari, who waited her whole life', 'devotion rewarded late but fully', 'An old forest woman waits decades for Rama, gathering fruit each day in case he comes. When he finally arrives she offers what she has. The Ramayana''s point is not the fruit but that the waiting itself was never wasted.', 'https://www.wisdomlib.org/hinduism/book/the-ramayana-of-valmiki', 130),
  ('ramayana:jatayu', 'purana', 'Ramayana of Valmiki', 'Aranya Kanda', 'Jatayu, an old bird against a demon king', 'acting despite certain defeat', 'An aged vulture sees Sita being carried away and attacks Ravana knowing exactly how it will end. He is cut down, but survives long enough to tell Rama which direction they went. Losing was not the same as failing.', 'https://www.wisdomlib.org/hinduism/book/the-ramayana-of-valmiki', 135),
  ('ramayana:hanuman-leap', 'purana', 'Ramayana of Valmiki', 'Sundara Kanda', 'Hanuman had to be reminded who he was', 'forgotten capability', 'Facing the ocean, the army despairs until Jambavan reminds Hanuman of the powers he had forgotten under a childhood curse. He does not gain anything new. He simply remembers, and crosses.', 'https://www.wisdomlib.org/hinduism/book/the-ramayana-of-valmiki', 135),
  ('ramayana:ahalya', 'purana', 'Ramayana of Valmiki', 'Bala Kanda', 'Ahalya, turned back from stone', 'redemption after long punishment', 'Cursed to lie forgotten as stone, Ahalya waits through ages for the dust of Rama''s feet. The Ramayana treats her restoration as ordinary, not exceptional — the point is that no exile from grace was ever meant to be permanent.', 'https://www.wisdomlib.org/hinduism/book/the-ramayana-of-valmiki', 120),
  ('ramayana:bharata-sandals', 'purana', 'Ramayana of Valmiki', 'Ayodhya Kanda', 'Bharata rules from beside the throne', 'power refused', 'Handed a kingdom he never wanted, Bharata places Rama''s sandals on the throne and governs for fourteen years from a lower seat, living as an ascetic outside the city. He holds the office without ever taking the honour.', 'https://www.wisdomlib.org/hinduism/book/the-ramayana-of-valmiki', 125),
  ('ramayana:kevat', 'purana', 'Ramayana of Valmiki', 'Ayodhya Kanda', 'The boatman who washed Rama''s feet first', 'faith with a touch of humour', 'The ferryman refuses to let Rama board until he has washed his feet — having heard what happened to a stone that touched that dust, he is not risking his only boat. Devotion here arrives as affection and wit rather than solemnity.', 'https://www.wisdomlib.org/hinduism/book/the-ramayana-of-valmiki', 125),
  ('purana:matsya:manu-flood', 'purana', 'Matsya Purana', 'Opening chapters — the Matsya avatara', 'The fish that asked to be saved first', 'heeding a warning while there is still time', 'A tiny fish in Manu''s cupped hands begs for protection, then outgrows every bowl, pot, lake and river he moves it to, until it fills the ocean. Only then does it tell him a flood is coming and to build the boat. The rescue was rehearsed long before the emergency.', 'https://en.wikipedia.org/wiki/Matsya_Purana', 130),
  ('purana:matsya:enumeration', 'purana', 'Matsya Purana', 'Chapter 53', 'The book that counts the other books', 'knowing the shape of a tradition', 'The Matsya Purana is the text that lists all eighteen Maha Puranas and their verse counts, totalling some four hundred thousand verses. It is the tradition pausing to take stock of itself and hand the reader a map.', 'https://en.wikipedia.org/wiki/Matsya_Purana', 100),
  ('purana:matsya:dana', 'purana', 'Matsya Purana', 'Chapters on dana and vrata', 'Giving measured by what it costs you', 'sincerity in generosity', 'Long sections of the Matsya Purana set out the forms of giving and the vows that structure a year. The recurring test is not the size of the gift but whether the giver felt its absence, and whether the receiver was left with their dignity.', 'https://en.wikipedia.org/wiki/Matsya_Purana', 105),
  ('purana:matsya:narmada', 'purana', 'Matsya Purana', 'Narmada Mahatmya', 'The river you do not have to enter', 'grace that does not require the ritual', 'The Matsya Purana says of the Narmada that the Ganga must be bathed in and the Yamuna touched, but the Narmada purifies by sight alone. Of all the tradition''s claims about holy water, it is the one asking least of the person standing there.', 'https://en.wikipedia.org/wiki/Matsya_Purana', 120),
  ('purana:matsya:prayaga', 'purana', 'Matsya Purana', 'Prayaga Mahatmya', 'Where two rivers and one invisible river meet', 'a meeting point taken on trust', 'At Prayaga the Ganga and Yamuna visibly join, and the tradition insists a third river joins them unseen. The Purana''s description spends more attention on the one nobody can point to than on the two anyone can.', 'https://en.wikipedia.org/wiki/Matsya_Purana', 115),
  ('purana:matsya:churning', 'purana', 'Matsya Purana', 'Chapters on the churning of the ocean', 'Enemies holding opposite ends of the same rope', 'cooperation with people you intend to outlast', 'Gods and demons cannot obtain the nectar alone, so they churn the ocean together, holding opposite ends of a serpent, for an age. The Purana does not soften the ending: the alliance was always going to break the moment the pot appeared.', 'https://en.wikipedia.org/wiki/Matsya_Purana', 130),
  ('purana:matsya:vastu', 'purana', 'Matsya Purana', 'Chapters on architecture', 'The being buried under every building', 'order imposed on something unruly', 'The Purana''s building chapters rest on the vastu purusha, a figure pinned face-down beneath the ground plan with a deity holding each limb. Every house is described as built on top of something held down.', 'https://en.wikipedia.org/wiki/Matsya_Purana', 105),
  ('purana:matsya:yayati', 'purana', 'Matsya Purana', 'Chapters on the lunar dynasty', 'The king who borrowed his son''s youth', 'appetite that a lifetime does not exhaust', 'Cursed with premature age, Yayati asks his sons to trade their youth for his old age. Only the youngest agrees. Yayati takes it and spends another thousand years on pleasure, then admits at the end that desire is never put out by feeding it.', 'https://en.wikipedia.org/wiki/Matsya_Purana', 130),
  ('purana:matsya:future-kings', 'purana', 'Matsya Purana', 'Chapters on the future dynasties', 'The kings who had not been born yet', 'power described in advance and in the past tense', 'The Purana lists rulers of ages still to come as though recalling them, ending each dynasty with the number of years it lasted. The literary effect is deliberate: every reign is already over by the time it is named.', 'https://en.wikipedia.org/wiki/Matsya_Purana', 105),
  ('purana:matsya:taraka', 'purana', 'Matsya Purana', 'Chapters on the birth of Skanda', 'The demon who chose how he would die', 'a loophole built into one''s own protection', 'Taraka takes a boon that only a son of Shiva can kill him, believing the ascetic will never have one. The gods spend the rest of the story arranging exactly that. The safeguard names the way it will fail.', 'https://en.wikipedia.org/wiki/Matsya_Purana', 125),
  ('purana:matsya:fourteen-manus', 'purana', 'Matsya Purana', 'Chapters on the Manvantaras', 'Fourteen times the world has started over', 'an ending that is not the ending', 'Each age has its own Manu, its own gods, its own sages, and its own dissolution. The Purana counts fourteen, places the reader in the seventh, and moves on without comment.', 'https://en.wikipedia.org/wiki/Matsya_Purana', 110),
  ('purana:matsya:shraddha', 'purana', 'Matsya Purana', 'Chapters on shraddha', 'Feeding people who cannot eat', 'duty owed backwards', 'The rites for the dead are laid out in detail — who is fed, on what day, in what order. The Purana is clear that the offering reaches the ancestors through the guests actually eating it, which makes the ritual a meal for the living.', 'https://en.wikipedia.org/wiki/Matsya_Purana', 100),
  ('purana:kurma:tortoise', 'purana', 'Kurma Purana', 'Framing narrative — the Kurma avatara', 'The one holding everything up is underwater', 'invisible support', 'When Mount Mandara began to sink during the churning of the ocean, Vishnu took the form of a tortoise and went beneath it. Gods and demons pulled at the surface and took the credit. The thing that made it possible was never once seen.', 'https://en.wikipedia.org/wiki/Kurma_Purana', 130),
  ('purana:kurma:ishvara-gita', 'purana', 'Kurma Purana', 'Uttara Vibhaga — the Ishvara Gita', 'The other Gita, spoken by Shiva', 'knowledge and the settled mind', 'The Kurma Purana carries the Ishvara Gita, a Shaiva counterpart to the Bhagavad Gita in which Shiva teaches the sages of the Daruka forest. Its instruction is the same at the root: know what you actually are, and act without agitation.', 'https://en.wikipedia.org/wiki/Kurma_Purana', 110),
  ('purana:kurma:ashramas', 'purana', 'Kurma Purana', 'Chapters on dharma and the ashramas', 'There is a season for each thing you owe', 'life stages and duty', 'The Kurma Purana lays out the stages of a life — study, household, withdrawal, renunciation — and insists each has its own duties. Trying to live the fourth while owing the second is presented not as devotion but as evasion.', 'https://en.wikipedia.org/wiki/Kurma_Purana', 105),
  ('purana:kurma:vyasa-gita', 'purana', 'Kurma Purana', 'Uttara Vibhaga — the Vyasa Gita', 'The second sermon in the same book', 'a teaching restated for a different listener', 'Having given the Ishvara Gita, the Kurma Purana gives another, spoken by Vyasa to sages who want it in plainer terms. The tradition evidently did not think one telling was enough, even inside a single text.', 'https://en.wikipedia.org/wiki/Kurma_Purana', 110),
  ('purana:kurma:naimisha', 'purana', 'Kurma Purana', 'Purva Vibhaga — the frame', 'The forest where somebody had to ask first', 'knowledge that waits to be requested', 'Every Purana opens the same way: sages in the Naimisha forest put a question to a storyteller, and the book is the answer. Nothing in the tradition is presented as arriving unasked, which is a claim about how teaching works.', 'https://en.wikipedia.org/wiki/Kurma_Purana', 105),
  ('purana:kurma:mandara-sinking', 'purana', 'Kurma Purana', 'Framing narrative — the Kurma avatara', 'The mountain that would not stay up', 'an effort that fails for want of a foundation', 'The churning begins, and the mountain being used as the rod immediately starts sinking into the seabed. All the strength on both ropes is worth nothing until something goes underneath and takes the weight where nobody can see it.', 'https://en.wikipedia.org/wiki/Kurma_Purana', 125),
  ('purana:kurma:hari-hara', 'purana', 'Kurma Purana', 'Purva Vibhaga', 'Two gods, one body', 'an argument the text refuses to have', 'Asked which of Vishnu and Shiva is greater, the Kurma Purana answers by describing them as halves of one form. It is a Vaishnava text spoken by Vishnu that gives its longest sermon to Shiva, and it treats the rivalry as a misunderstanding.', 'https://en.wikipedia.org/wiki/Kurma_Purana', 120),
  ('purana:kurma:pashupata-vow', 'purana', 'Kurma Purana', 'Chapters on the vow', 'Ash, and nothing else', 'stripping a practice down to what is left', 'The ascetic''s discipline is described with almost nothing in it: ash on the body, a place outside the village, and a name repeated. The Purana presents the absence of equipment as the point rather than as poverty.', 'https://en.wikipedia.org/wiki/Kurma_Purana', 110),
  ('purana:kurma:pralaya', 'purana', 'Kurma Purana', 'Chapters on dissolution', 'How a world is put away', 'endings described without panic', 'The Purana takes the world apart in order — earth into water, water into fire, fire into air, air into space — each element dissolving into the one it came from. It is described as tidying, not catastrophe.', 'https://en.wikipedia.org/wiki/Kurma_Purana', 115),
  ('purana:kurma:yugas', 'purana', 'Kurma Purana', 'Chapters on the ages', 'What each age asks of a person', 'the effort a time demands', 'Meditation in the first age, sacrifice in the second, worship in the third, and in the last simply saying the name. The Kurma Purana''s account of decline is also an account of the entry price falling.', 'https://en.wikipedia.org/wiki/Kurma_Purana', 115),
  ('purana:kurma:dvipas', 'purana', 'Kurma Purana', 'Chapters on the world''s divisions', 'Standing on one leaf of a very large map', 'scale that puts a place in proportion', 'The known land is placed as one region of one island among seven, ringed by oceans. The geography is not accurate and was not meant to be; it is a device for making the reader''s own country small.', 'https://en.wikipedia.org/wiki/Kurma_Purana', 95),
  ('purana:kurma:householder-duty', 'purana', 'Kurma Purana', 'Chapters on dharma', 'The one whose work feeds the others', 'ordinary obligation as the harder path', 'Of the four stages of life, the Purana singles out the householder as the one supporting the other three, and says so bluntly: the renunciate eats because somebody stayed behind and cooked.', 'https://en.wikipedia.org/wiki/Kurma_Purana', 120),
  ('purana:varaha:lifting-earth', 'purana', 'Varaha Purana', 'Framing narrative — the Varaha avatara', 'The earth was carried out on a tusk', 'rescue from the depths', 'The whole Varaha Purana is spoken while the rescue is still happening: Vishnu as the boar has dived into the cosmic waters, lifted the drowned earth on his tusk, and is answering her questions on the way back up.', 'https://en.wikipedia.org/wiki/Varaha_Purana', 125),
  ('purana:varaha:earth-questions', 'purana', 'Varaha Purana', 'Dialogue of Bhudevi and Varaha', 'The earth asks who is worth saving', 'worthiness and grace', 'Bhudevi, the earth goddess, questions her rescuer about vows, giving and who deserves deliverance. The answers keep returning to the same place: deliverance is not a reward issued for a score, or she herself would still be under the water.', 'https://en.wikipedia.org/wiki/Varaha_Purana', 110),
  ('purana:varaha:mathura', 'purana', 'Varaha Purana', 'Mathura Mahatmya', 'Why the ground at Mathura is different', 'sacred place and memory', 'The Varaha Purana''s praise of Mathura treats a place as a form of memory — soil that holds what happened on it. Pilgrimage becomes less about travel than about standing where something true occurred and letting it work on you.', 'https://en.wikipedia.org/wiki/Varaha_Purana', 100),
  ('purana:varaha:hiranyaksha', 'purana', 'Varaha Purana', 'Framing narrative — the Varaha avatara', 'The demon who rolled up the earth and left', 'a theft nobody could follow', 'Hiranyaksha takes the earth itself and hides it under the cosmic waters, where no god can reach. The rescue requires becoming something that can go down there — which is why the answer to him is a boar rather than an army.', 'https://en.wikipedia.org/wiki/Varaha_Purana', 130),
  ('purana:varaha:dharma-taught', 'purana', 'Varaha Purana', 'Dialogue of Bhudevi and Varaha', 'The earth asks how to be lived on', 'instruction given to the ground itself', 'Having been carried to safety, Bhudevi does not thank her rescuer and stop. She asks what the beings on her back are supposed to do, and the rest of the Purana is the answer to that one question.', 'https://en.wikipedia.org/wiki/Varaha_Purana', 120),
  ('purana:varaha:vratas', 'purana', 'Varaha Purana', 'Chapters on vratas', 'Promises kept on particular days', 'structure that carries you when resolve does not', 'The vrata chapters attach observance to fixed dates rather than to how a person feels. The Purana''s assumption is that anyone relying on their own motivation will stop, and that a calendar will not.', 'https://en.wikipedia.org/wiki/Varaha_Purana', 105),
  ('purana:varaha:kokamukha', 'purana', 'Varaha Purana', 'Kokamukha Mahatmya', 'A holy place at the edge of the map', 'sanctity far from anywhere convenient', 'The Purana devotes long passages to a tirtha in the far northern hills that few of its readers could ever have reached. Distance is treated as part of what the place is worth, not as an obstacle to be apologised for.', 'https://en.wikipedia.org/wiki/Varaha_Purana', 95),
  ('purana:varaha:forms-of-vishnu', 'purana', 'Varaha Purana', 'Chapters on the forms of Vishnu', 'The same one, described differently', 'many descriptions of a single thing', 'The Purana catalogues form after form — reclining, standing, four-armed, boar-headed — and insists throughout that the multiplicity is in the describing, not in the described.', 'https://en.wikipedia.org/wiki/Varaha_Purana', 100),
  ('purana:varaha:goddess-forms', 'purana', 'Varaha Purana', 'Chapters on the goddesses', 'The mothers who arrive when it is already bad', 'help that comes in numbers', 'The Purana describes the band of mother goddesses emerging when a single opponent has proved too much for anyone acting alone. Their appearance in a text is reliably a sign that the situation has gone past negotiation.', 'https://en.wikipedia.org/wiki/Varaha_Purana', 115),
  ('purana:varaha:shraddha', 'purana', 'Varaha Purana', 'Chapters on shraddha', 'The obligation that outlives the person', 'a debt that does not lapse', 'Rites for the dead are described as owed regardless of how the relationship went. The Purana makes no allowance for a difficult father, which is precisely what makes the instruction hard.', 'https://en.wikipedia.org/wiki/Varaha_Purana', 110),
  ('purana:varaha:giving', 'purana', 'Varaha Purana', 'Chapters on dana', 'What is given, and to whom, and when', 'generosity with its conditions named', 'The Purana is specific about giving: at the right time, to someone who needs it, without announcing it, and without expecting the recipient to be grateful in a visible way. Each condition removes a way of getting credit.', 'https://en.wikipedia.org/wiki/Varaha_Purana', 120),
  ('purana:varaha:mathura-circuit', 'purana', 'Varaha Purana', 'Mathura Mahatmya', 'Walking the same few miles on purpose', 'repetition as devotion', 'The circuit around Mathura is laid out stop by stop, to be walked in order, more than once. The Purana treats the second and tenth walk as worth more than the first, which is not how a sightseer would rank them.', 'https://en.wikipedia.org/wiki/Varaha_Purana', 100),
  ('purana:vamana:three-steps', 'purana', 'Vamana Purana', 'Framing narrative — the Vamana avatara', 'Three paces from a man who had everything', 'humility outmatching power', 'A dwarf asks the world-conquering Bali for three paces of land and is warned it is a trap. Bali gives anyway rather than break his word, and the third step has nowhere left to fall but his own head. He is honoured above the gods for losing.', 'https://en.wikipedia.org/wiki/Vamana_Purana', 130),
  ('purana:vamana:aditi-penance', 'purana', 'Vamana Purana', 'Chapters on the birth of Vamana', 'A mother''s austerity before the rescue', 'patience before deliverance', 'Before the dwarf ever walks into Bali''s hall, Aditi undertakes long austerity for a son who can set things right. The Vamana Purana spends its opening on the waiting, not the victory — the part nobody retells.', 'https://en.wikipedia.org/wiki/Vamana_Purana', 105),
  ('purana:vamana:trivikrama', 'purana', 'Vamana Purana', 'The Trivikrama form', 'The small form was the real one', 'underestimation', 'The figure everyone in the hall dismissed expands into Trivikrama, who covers earth and sky in two strides. The Purana''s point is not the vast form but that it was there the whole time, standing quietly and asking politely.', 'https://en.wikipedia.org/wiki/Vamana_Purana', 120),
  ('purana:vamana:shukra-warning', 'purana', 'Vamana Purana', 'Chapters on Bali''s sacrifice', 'The advisor who lost an eye stopping a gift', 'loyalty that will not be thanked', 'Shukracharya recognises the dwarf and tries to stop the grant, first by argument and then by shrinking himself to block the spout of the water jar. A blade of grass is pushed through to clear it, and he loses the eye. His king overrules him anyway.', 'https://en.wikipedia.org/wiki/Vamana_Purana', 130),
  ('purana:vamana:ganga-from-foot', 'purana', 'Vamana Purana', 'The Trivikrama form', 'The river that started at a footstep', 'something enormous beginning as a side effect', 'As the second stride reaches the top of the universe, the foot breaks the shell of the world and water pours through the crack. The Ganga, in this telling, is not a gift that was planned. It is what came in through the hole.', 'https://en.wikipedia.org/wiki/Vamana_Purana', 125),
  ('purana:vamana:bali-in-patala', 'purana', 'Vamana Purana', 'Chapters on Bali', 'The defeated king who was given a door', 'losing everything and being honoured for it', 'Having lost the three worlds for keeping his word, Bali is sent below — and Vishnu takes the post of doorkeeper outside his hall. The Purana''s judgement on who won is delivered entirely through where each of them ends up standing.', 'https://en.wikipedia.org/wiki/Vamana_Purana', 130),
  ('purana:vamana:prahlada-counsel', 'purana', 'Vamana Purana', 'Chapters on Bali''s sacrifice', 'The grandfather who told him to give it away', 'advice against one''s own family interest', 'Bali''s grandfather Prahlada, who survived his own father''s persecution, is the one who tells him not to refuse the dwarf. The counsel costs the family its empire, and he gives it without hesitating.', 'https://en.wikipedia.org/wiki/Vamana_Purana', 120),
  ('purana:vamana:kurukshetra', 'purana', 'Vamana Purana', 'Kurukshetra Mahatmya', 'The field before it was a battlefield', 'a place remembered for the wrong thing', 'Long before the war, the Purana describes Kurukshetra as a plain of ponds and shrines where a king named Kuru ploughed the ground as an act of devotion. Everything the name now means came later.', 'https://en.wikipedia.org/wiki/Vamana_Purana', 120),
  ('purana:vamana:skull-in-hand', 'purana', 'Vamana Purana', 'Chapters on Shiva''s wandering', 'The god who begged with a skull', 'carrying a consequence in public', 'Shiva wanders as a beggar with a skull stuck to his hand that will not come free, unable to fill it. The Purana does not let him off quickly. He carries the visible evidence of what he did for as long as it takes.', 'https://en.wikipedia.org/wiki/Vamana_Purana', 125),
  ('purana:vamana:parvati-austerity', 'purana', 'Vamana Purana', 'Chapters on the goddess', 'The one who was called dark and left', 'a remark that changes a life', 'Stung by a careless word about her complexion, Parvati goes away and undertakes austerity until she is transformed. The Purana''s interest is in how small the original comment was, and how completely it was answered.', 'https://en.wikipedia.org/wiki/Vamana_Purana', 125),
  ('purana:vamana:andhaka-end', 'purana', 'Vamana Purana', 'Chapters on Andhaka', 'The blood that made more of him', 'a fight that feeds on being fought', 'Every drop of Andhaka''s blood that touches the ground becomes another Andhaka, so the harder he is struck the more of him there is. He is beaten only when someone stops striking and starts catching.', 'https://en.wikipedia.org/wiki/Vamana_Purana', 120),
  ('purana:vamana:aditi-patience', 'purana', 'Vamana Purana', 'Chapters on the birth of Vamana', 'A mother who waited out a war', 'the long unremarkable part of a rescue', 'Aditi''s sons are driven out and she is left with nothing to do but keep a vow, month after month, on the instruction of her husband. The Purana gives the waiting more space than the victory that follows it.', 'https://en.wikipedia.org/wiki/Vamana_Purana', 115),
  ('purana:bhavishya:name', 'purana', 'Bhavishya Purana', 'Framing of the text', 'The Purana written in the future tense', 'time and consequence', 'Alone among the eighteen, the Bhavishya Purana is framed as prophecy — its name simply means ''the future''. Its working assumption is that what is coming is not arbitrary but grown from what is being done now.', 'https://en.wikipedia.org/wiki/Bhavishya_Purana', 115),
  ('purana:bhavishya:surya', 'purana', 'Bhavishya Purana', 'Brahma Parva — sun worship', 'The oldest medicine is to face the light', 'discipline and renewal', 'Large parts of the Bhavishya Purana concern the worship of Surya, including the priestly lineages who tended sun temples. Its prescription is unglamorous and daily: rise, face the light, begin again.', 'https://en.wikipedia.org/wiki/Bhavishya_Purana', 110),
  ('purana:bhavishya:household-year', 'purana', 'Bhavishya Purana', 'Chapters on vratas and festivals', 'A year built out of small observances', 'rhythm and remembrance', 'The Bhavishya Purana organises the calendar into fasts, festivals and duties. The architecture is deliberate: a person cannot hold a spiritual intention continuously, so the year is built to keep returning them to it.', 'https://en.wikipedia.org/wiki/Bhavishya_Purana', 100),
  ('purana:bhavishya:holika', 'purana', 'Bhavishya Purana', 'Uttara Parva — the festival chapters', 'The fire that burnt the wrong person', 'protection that fails the one holding it', 'Holika has a boon against fire and carries her nephew Prahlada into the flames to kill him. She burns and the child does not. The Purana is precise about why: a protection given for one purpose stopped working the moment it was used for another.', 'https://en.wikipedia.org/wiki/Bhavishya_Purana', 130),
  ('purana:bhavishya:maga-priests', 'purana', 'Bhavishya Purana', 'Brahma Parva', 'The priests who were sent for from abroad', 'borrowing what you do not have', 'To serve the new sun temple, priests are brought from a land across the sea because nobody at home knows the rite. The Purana records the import without embarrassment, which makes it one of the tradition''s franker moments.', 'https://en.wikipedia.org/wiki/Bhavishya_Purana', 105),
  ('purana:bhavishya:water-gift', 'purana', 'Bhavishya Purana', 'Uttara Parva — chapters on dana', 'The best thing to give away in May', 'generosity matched to the season', 'In the hot months the Purana rates a jar of cool water and a shaded place to drink it above gold. The ranking of gifts changes with the calendar, because what a person needs in June is not what they need in December.', 'https://en.wikipedia.org/wiki/Bhavishya_Purana', 115),
  ('purana:bhavishya:planting-trees', 'purana', 'Bhavishya Purana', 'Uttara Parva — chapters on merit', 'Shade you will never sit in', 'work whose benefit goes to strangers', 'Planting trees and digging wells are ranked among the highest acts, and the Purana notes what they have in common: the person who does the work is usually dead before the benefit is at its fullest.', 'https://en.wikipedia.org/wiki/Bhavishya_Purana', 125),
  ('purana:bhavishya:naga-worship', 'purana', 'Bhavishya Purana', 'Uttara Parva — the vrata chapters', 'Offering milk to what you are afraid of', 'respect for a danger rather than war against it', 'On the appointed day, milk is set out for snakes rather than snakes being hunted. The Purana''s logic is not sentimental: the creature was there first, it will still be there tomorrow, and coexistence has to be arranged.', 'https://en.wikipedia.org/wiki/Bhavishya_Purana', 110),
  ('purana:bhavishya:pratisarga', 'purana', 'Bhavishya Purana', 'Pratisarga Parva', 'The chapters that kept being added to', 'a text that would not stay finished', 'The Purana''s section on things to come was extended by later hands for centuries, each generation writing its own present into a book claiming to have foreseen it. Read honestly, it is a record of what people kept wanting scripture to have known.', 'https://en.wikipedia.org/wiki/Bhavishya_Purana', 100),
  ('purana:bhavishya:twelve-suns', 'purana', 'Bhavishya Purana', 'Brahma Parva — sun worship', 'One sun with twelve names', 'the same source in different months', 'The sun is given a distinct name and character for each month of the year — fierce in one, mild in another. The Purana is describing a single body and insisting that how it meets you changes.', 'https://en.wikipedia.org/wiki/Bhavishya_Purana', 100),
  ('purana:bhavishya:ritucharya', 'purana', 'Bhavishya Purana', 'Chapters on the seasons', 'Eating differently in different weather', 'living with the year instead of against it', 'What to eat, when to bathe, when to travel and when to stay in are all set by season. The instruction assumes a body that is part of the weather rather than sheltered from it.', 'https://en.wikipedia.org/wiki/Bhavishya_Purana', 95),
  ('purana:bhavishya:bhishma-panchaka', 'purana', 'Bhavishya Purana', 'Uttara Parva — the vrata chapters', 'Five days named after a dying man', 'an observance built on somebody''s last words', 'The five-day fast is named for Bhishma, who spent his final days on a bed of arrows answering questions about duty. The Purana ties the observance to the fact that he kept teaching while he was dying.', 'https://en.wikipedia.org/wiki/Bhavishya_Purana', 115),
  ('purana:brahmavaivarta:radha', 'purana', 'Brahmavaivarta Purana', 'Krishna Janma Khanda', 'Two names for one thing', 'love as inseparability', 'The Brahmavaivarta Purana refuses to treat Radha as Krishna''s companion and instead treats them as one reality described from two sides. Devotion here is not reaching toward the divine but recognising you were never separate.', 'https://en.wikipedia.org/wiki/Brahmavaivarta_Purana', 125),
  ('purana:brahmavaivarta:ganapati', 'purana', 'Brahmavaivarta Purana', 'Ganapati Khanda', 'The one you greet before beginning', 'obstacles and beginnings', 'A whole book of the Brahmavaivarta Purana belongs to Ganesha. He is not asked to clear the road so much as consulted about whether it is the right road — which is why nothing is meant to start without him.', 'https://en.wikipedia.org/wiki/Brahmavaivarta_Purana', 120),
  ('purana:brahmavaivarta:prakriti', 'purana', 'Brahmavaivarta Purana', 'Prakriti Khanda', 'Nature is not a backdrop', 'the feminine principle', 'The Prakriti Khanda treats the goddess as nature itself — not scenery for a divine drama but the active power without which nothing at all occurs. Consciousness may be still; everything that moves, moves as her.', 'https://en.wikipedia.org/wiki/Brahmavaivarta_Purana', 110),
  ('purana:brahmavaivarta:ganesha-head', 'purana', 'Brahmavaivarta Purana', 'Ganapati Khanda', 'The guest who was asked not to look', 'harm done by someone who warned you', 'Every god comes to see the newborn. Shani stays back and explains that his glance burns whatever it falls on. Pressed and pressed again to look, he finally does, and the child''s head is gone. The Purana blames the insisting, not the looking.', 'https://en.wikipedia.org/wiki/Brahmavaivarta_Purana', 135),
  ('purana:brahmavaivarta:tulsi', 'purana', 'Brahmavaivarta Purana', 'Prakriti Khanda', 'The wife whose faithfulness was the shield', 'protection that has to be broken to be beaten', 'Shankhachuda cannot be killed while his wife Tulsi''s devotion is intact, so the war is won by deceiving her rather than by defeating him. She is given the form of a plant afterwards, and the plant is kept in every courtyard.', 'https://en.wikipedia.org/wiki/Brahmavaivarta_Purana', 130),
  ('purana:brahmavaivarta:goloka', 'purana', 'Brahmavaivarta Purana', 'Krishna Janma Khanda', 'The world above the worlds', 'a home that was never left', 'The Purana places a realm above every heaven the other texts describe, and says the cowherd boy of Vrindavan never actually departed from it. Everything that happens on earth is happening to someone who is already home.', 'https://en.wikipedia.org/wiki/Brahmavaivarta_Purana', 115),
  ('purana:brahmavaivarta:five-goddesses', 'purana', 'Brahmavaivarta Purana', 'Prakriti Khanda', 'One power, counted five ways', 'aspects of a single strength', 'Durga, Radha, Lakshmi, Saraswati and Savitri are described as five portions of one original power — force, love, sustenance, knowledge and speech. The Purana treats the division as convenience for the describer.', 'https://en.wikipedia.org/wiki/Brahmavaivarta_Purana', 110),
  ('purana:brahmavaivarta:sudama-curse', 'purana', 'Brahmavaivarta Purana', 'Krishna Janma Khanda', 'The attendant cursed for doing his job', 'punishment falling on the obedient', 'Sudama blocks Radha at a door because he was told to, and is cursed for it into a demon''s birth. The Purana lets the injustice stand without tidying it, and follows him all the way through the consequence.', 'https://en.wikipedia.org/wiki/Brahmavaivarta_Purana', 120),
  ('purana:brahmavaivarta:flute', 'purana', 'Brahmavaivarta Purana', 'Krishna Janma Khanda', 'The sound that emptied the houses', 'a call that arrives at an inconvenient hour', 'The flute is heard at night, and women leave half-finished work, sleeping husbands and unlit lamps to follow it. The Purana does not present this as tidy devotion. It presents it as something that could not be resisted.', 'https://en.wikipedia.org/wiki/Brahmavaivarta_Purana', 125),
  ('purana:brahmavaivarta:karma-accounts', 'purana', 'Brahmavaivarta Purana', 'Brahma Khanda', 'Nothing is written off', 'consequences that wait', 'The Purana insists an action''s result arrives whether or not anyone remembers the action, and that delay is not cancellation. It is the least comforting doctrine in the text and it is stated most plainly.', 'https://en.wikipedia.org/wiki/Brahmavaivarta_Purana', 120),
  ('purana:brahmavaivarta:savitri-dialogue', 'purana', 'Brahmavaivarta Purana', 'Prakriti Khanda', 'Questions put to death, and answered', 'arguing rather than pleading', 'Savitri does not beg Yama for her husband''s life. She follows him and keeps talking — about duty, about what a good person owes, about what he himself has just said — until he grants what she never directly asked for.', 'https://en.wikipedia.org/wiki/Brahmavaivarta_Purana', 130),
  ('purana:brahmavaivarta:speech-goddess', 'purana', 'Brahmavaivarta Purana', 'Prakriti Khanda', 'The goddess who is the words themselves', 'language as something received', 'Saraswati is not described as presiding over speech but as being it. On that account every sentence a person manages is borrowed, which is why the Purana treats careless words as a specific kind of ingratitude.', 'https://en.wikipedia.org/wiki/Brahmavaivarta_Purana', 110)
