-- Curated Purana / Upanishad / Ramayana corpus (234 topics).
-- Generated from src/lib/sources/puranas.ts — the exact rows `npm run seed:topics`
-- would write, minus the 700 Gita verses (those need the live Vedic API).
--
-- Safe to paste into the Supabase SQL editor as many times as you like:
-- ON CONFLICT DO NOTHING leaves already-used topics untouched.
--
-- Every one of the eighteen Maha Puranas now carries at least ten episodes.
-- That floor is what the rotation needs: it hands out one Purana per day and
-- skips any with nothing unused left, so a book with two entries was being
-- dropped from the rotation for good within a week of going live.

on conflict (topic_key) do nothing;

-- What you have now:
select scripture, count(*) as total, count(*) filter (where times_used = 0) as remaining
from public.topic_ledger group by scripture order by remaining desc;
